'use client';

import { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import {
  Plus,
  Search,
  Edit3,
  Trash2,
  Upload,
  X,
  Mail,
  Building2,
  Loader2
} from 'lucide-react';
import toast from 'react-hot-toast';

interface FacultyRecord {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  department?: { id: string; name: string } | null;
  departmentId?: string | null;
  designation: string;
  subjects?: string[];
  status: string;
}

interface Department {
  id: string;
  name: string;
}

export default function FacultyManagement() {
  const [list, setList] = useState<FacultyRecord[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  const [showModal, setShowModal] = useState(false);
  const [modalType, setModalType] = useState<'create' | 'edit'>('create');
  const [selectedFaculty, setSelectedFaculty] = useState<FacultyRecord | null>(null);

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [departmentId, setDepartmentId] = useState('');
  const [designation, setDesignation] = useState('');
  const [subjects, setSubjects] = useState('');

  const [csvFile, setCsvFile] = useState<File | null>(null);
  const [showImportModal, setShowImportModal] = useState(false);

  const loadData = async () => {
    try {
      setLoading(true);
      const [facRes, deptRes] = await Promise.all([
        api.get('/admin/faculty'),
        api.get('/admin/departments'),
      ]);
      if (facRes.data?.success) setList(facRes.data.data);
      if (deptRes.data?.success) setDepartments(deptRes.data.data);
    } catch (err) {
      toast.error('Failed to load faculty data');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadData(); }, []);

  const handleOpenCreate = () => {
    setModalType('create');
    setSelectedFaculty(null);
    setFirstName(''); setLastName(''); setEmail(''); setDepartmentId(''); setDesignation(''); setSubjects('');
    setShowModal(true);
  };

  const handleOpenEdit = (f: FacultyRecord) => {
    setModalType('edit');
    setSelectedFaculty(f);
    setFirstName(f.firstName);
    setLastName(f.lastName);
    setEmail(f.email);
    setDepartmentId(f.departmentId || '');
    setDesignation(f.designation || '');
    setSubjects(f.subjects?.join(', ') || '');
    setShowModal(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!firstName || !lastName || !email) {
      toast.error('First Name, Last Name, and Email are required.');
      return;
    }

    const payload: Record<string, unknown> = {
      firstName,
      lastName,
      email,
      role: 'FACULTY',
      departmentId: departmentId || undefined,
      designation: designation || undefined,
      subjects: subjects ? subjects.split(',').map(s => s.trim()).filter(Boolean) : [],
    };

    try {
      if (modalType === 'create') {
        const res = await api.post('/admin/faculty', payload);
        if (res.data?.success) {
          toast.success('Faculty member created successfully!');
          setShowModal(false);
          loadData();
        }
      } else if (selectedFaculty) {
        const res = await api.put(`/admin/faculty/${selectedFaculty.id}`, payload);
        if (res.data?.success) {
          toast.success('Faculty member updated successfully!');
          setShowModal(false);
          loadData();
        }
      }
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Operation failed');
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this faculty member?')) return;
    try {
      const res = await api.delete(`/admin/faculty/${id}`);
      if (res.data?.success) {
        toast.success('Faculty member deleted.');
        loadData();
      }
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Deletion failed');
    }
  };

  const handleImportCsv = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!csvFile) {
      toast.error('Please select a CSV file.');
      return;
    }
    const formData = new FormData();
    formData.append('file', csvFile);
    try {
      const res = await api.post('/admin/faculty/import', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      if (res.data?.success) {
        toast.success('Faculty members imported successfully!');
        setShowImportModal(false);
        setCsvFile(null);
        loadData();
      }
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Import failed');
    }
  };

  const filteredList = list.filter(f =>
    `${f.firstName} ${f.lastName}`.toLowerCase().includes(search.toLowerCase()) ||
    f.email.toLowerCase().includes(search.toLowerCase()) ||
    (f.designation || '').toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Faculty Management</h2>
          <p className="text-gray-600">Manage faculty profiles, departments, and bulk imports.</p>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setShowImportModal(true)}
            className="border border-gray-300 hover:bg-gray-50 bg-white text-gray-700 font-semibold py-2 px-4 rounded-lg text-sm flex items-center gap-2 transition-all shadow-sm">
            <Upload size={16} /> Bulk Import
          </button>
          <button onClick={handleOpenCreate}
            className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg text-sm flex items-center gap-2 transition-all shadow-sm">
            <Plus size={18} /> Add Faculty
          </button>
        </div>
      </div>

      <div className="bg-white rounded-lg border border-gray-200 shadow-sm p-6 space-y-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-3 text-gray-400" size={18} />
          <input
            type="text"
            placeholder="Search faculty by name, email, or designation..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-gray-50 border border-gray-300 rounded-lg pl-10 pr-4 py-2 text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
          />
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-16">
            <div className="flex flex-col items-center gap-2">
              <Loader2 size={32} className="animate-spin text-blue-600" />
              <span className="text-gray-500">Loading faculty...</span>
            </div>
          </div>
        ) : filteredList.length === 0 ? (
          <div className="text-center py-16 text-gray-500 text-sm">No faculty members found. Create one to get started.</div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead>
                <tr className="border-b border-gray-200 bg-gray-50 text-gray-700 font-semibold">
                  <th className="px-4 py-3">Name</th>
                  <th className="px-4 py-3">Email</th>
                  <th className="px-4 py-3">Department</th>
                  <th className="px-4 py-3">Designation</th>
                  <th className="px-4 py-3">Subjects</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {filteredList.map((f) => (
                  <tr key={f.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-4 py-3">
                      <div className="font-semibold text-gray-900 flex items-center gap-2">
                        <Building2 size={16} className="text-blue-600" />
                        {f.firstName} {f.lastName}
                      </div>
                    </td>
                    <td className="px-4 py-3 text-gray-700">
                      <span className="flex items-center gap-1"><Mail size={14} /> {f.email}</span>
                    </td>
                    <td className="px-4 py-3 text-gray-700">{f.department?.name || '—'}</td>
                    <td className="px-4 py-3 text-gray-700 text-xs">{f.designation || '—'}</td>
                    <td className="px-4 py-3 text-gray-700 text-xs">
                      {f.subjects && f.subjects.length > 0 ? f.subjects.join(', ') : '—'}
                    </td>
                    <td className="px-4 py-3">
                      <span className={`px-3 py-1 rounded-full text-xs font-semibold ${f.status === 'ACTIVE' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                        {f.status || 'ACTIVE'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right">
                      <div className="flex items-center justify-end gap-2">
                        <button onClick={() => handleOpenEdit(f)} className="p-2 hover:bg-gray-100 rounded text-gray-600 hover:text-gray-900" title="Edit"><Edit3 size={16} /></button>
                        <button onClick={() => handleDelete(f.id)} className="p-2 hover:bg-red-50 hover:text-red-600 rounded text-gray-400" title="Delete"><Trash2 size={16} /></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="max-w-md w-full bg-white rounded-lg shadow-xl border border-gray-200 p-6 relative">
            <button onClick={() => setShowModal(false)} className="absolute right-4 top-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>
            <h3 className="text-lg font-bold text-gray-900 mb-4">
              {modalType === 'create' ? 'Add New Faculty Member' : 'Edit Faculty Member'}
            </h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">First Name *</label>
                  <input
                    type="text"
                    required
                    value={firstName}
                    onChange={(e) => setFirstName(e.target.value)}
                    className="w-full bg-gray-50 border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                    placeholder="John"
                  />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Last Name *</label>
                  <input
                    type="text"
                    required
                    value={lastName}
                    onChange={(e) => setLastName(e.target.value)}
                    className="w-full bg-gray-50 border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                    placeholder="Smith"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Email *</label>
                <input
                  type="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full bg-gray-50 border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                  placeholder="john.smith@school.edu"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Department</label>
                  <select
                    value={departmentId}
                    onChange={(e) => setDepartmentId(e.target.value)}
                    className="w-full bg-gray-50 border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                  >
                    <option value="">Select Department</option>
                    {departments.map((d) => (
                      <option key={d.id} value={d.id}>
                        {d.name}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1">Designation</label>
                  <input
                    type="text"
                    value={designation}
                    onChange={(e) => setDesignation(e.target.value)}
                    className="w-full bg-gray-50 border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                    placeholder="e.g. Assistant Professor"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Subjects (comma-separated)</label>
                <input
                  type="text"
                  value={subjects}
                  onChange={(e) => setSubjects(e.target.value)}
                  className="w-full bg-gray-50 border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                  placeholder="Math, Physics, Chemistry"
                />
              </div>
              <button
                type="submit"
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2.5 rounded-lg transition-all shadow-sm text-sm"
              >
                {modalType === 'create' ? 'Create Faculty' : 'Update Faculty'}
              </button>
            </form>
          </div>
        </div>
      )}

      {showImportModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="max-w-md w-full bg-white rounded-lg shadow-xl border border-gray-200 p-6 relative">
            <button onClick={() => { setShowImportModal(false); setCsvFile(null); }} className="absolute right-4 top-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>
            <h3 className="text-lg font-bold text-gray-900 mb-4">Bulk Import Faculty</h3>
            <form onSubmit={handleImportCsv} className="space-y-4">
              <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center cursor-pointer hover:bg-gray-50 transition-colors relative">
                <input
                  type="file"
                  accept=".csv"
                  required
                  onChange={(e) => setCsvFile(e.target.files?.[0] || null)}
                  className="absolute inset-0 opacity-0 cursor-pointer w-full h-full"
                />
                <Upload className="mx-auto text-blue-600 mb-2" size={32} />
                <span className="text-sm font-semibold text-gray-800 block">{csvFile ? csvFile.name : 'Click to select CSV file'}</span>
                <span className="text-xs text-gray-500 mt-1 block">Columns: firstName, lastName, email, departmentId, designation, subjects</span>
              </div>
              <button
                type="submit"
                disabled={!csvFile}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2.5 rounded-lg transition-all shadow-sm text-sm disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Import Faculty
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { Loader2 } from 'lucide-react';

interface DashboardStats {
  totalUsers: number;
  totalStudents: number;
  totalTeachers: number;
  totalFaculty: number;
  attendance: number;
  activeExams: number;
}

export default function AdminDashboard() {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        setLoading(true);
        setError(null);
        const response = await api.get('/admin/dashboard/stats');
        if (response.data?.data) {
          setStats(response.data.data);
        } else {
          setError('Failed to load dashboard statistics');
        }
      } catch (err: any) {
        setError(err?.message || 'Failed to load dashboard');
        console.error('Dashboard stats error:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, []);

  if (loading) {
    return (
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '400px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, color: '#6b7280' }}>
          <Loader2 size={20} className="animate-spin" />
          <span>Loading dashboard...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ padding: 20, background: '#fee2e2', border: '1px solid #fca5a5', borderRadius: 12, color: '#991b1b' }}>
        <h3 style={{ fontWeight: 600, marginBottom: 8 }}>Error Loading Dashboard</h3>
        <p>{error}</p>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      <div>
        <h1 style={{ fontSize: 28, fontWeight: 700, color: '#0f172a', marginBottom: 4 }}>Admin Dashboard</h1>
        <p style={{ fontSize: 14, color: '#6b7280' }}>Authorization Management Overview</p>
      </div>

      {stats && (
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
          gap: 16,
        }}>
          <div style={{ 
            background: '#fff', 
            padding: 20, 
            borderRadius: 12, 
            border: '1px solid #e5e7eb',
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
          }}>
            <div style={{ fontSize: 12, color: '#6b7280', fontWeight: 600, marginBottom: 8 }}>TOTAL USERS</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#0f172a' }}>{stats.totalUsers}</div>
          </div>

          <div style={{ 
            background: '#fff', 
            padding: 20, 
            borderRadius: 12, 
            border: '1px solid #e5e7eb',
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
          }}>
            <div style={{ fontSize: 12, color: '#6b7280', fontWeight: 600, marginBottom: 8 }}>TOTAL STUDENTS</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#0f172a' }}>{stats.totalStudents}</div>
          </div>

          <div style={{ 
            background: '#fff', 
            padding: 20, 
            borderRadius: 12, 
            border: '1px solid #e5e7eb',
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
          }}>
            <div style={{ fontSize: 12, color: '#6b7280', fontWeight: 600, marginBottom: 8 }}>TOTAL TEACHERS</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#0f172a' }}>{stats.totalTeachers}</div>
          </div>

          <div style={{ 
            background: '#fff', 
            padding: 20, 
            borderRadius: 12, 
            border: '1px solid #e5e7eb',
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
          }}>
            <div style={{ fontSize: 12, color: '#6b7280', fontWeight: 600, marginBottom: 8 }}>TOTAL FACULTY</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#0f172a' }}>{stats.totalFaculty}</div>
          </div>

          <div style={{ 
            background: '#fff', 
            padding: 20, 
            borderRadius: 12, 
            border: '1px solid #e5e7eb',
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
          }}>
            <div style={{ fontSize: 12, color: '#6b7280', fontWeight: 600, marginBottom: 8 }}>TODAY\'S ATTENDANCE</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#0f172a' }}>{stats.attendance}%</div>
          </div>

          <div style={{ 
            background: '#fff', 
            padding: 20, 
            borderRadius: 12, 
            border: '1px solid #e5e7eb',
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
          }}>
            <div style={{ fontSize: 12, color: '#6b7280', fontWeight: 600, marginBottom: 8 }}>ACTIVE EXAMS</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#0f172a' }}>{stats.activeExams}</div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { Settings as SettingsIcon, Save, Loader2 } from 'lucide-react';
import toast from 'react-hot-toast';

interface SettingsData {
  security: {
    passwordMinLength: number;
    requireSpecialChar: boolean;
    requireNumbers: boolean;
    mfaEnabled: boolean;
  };
  uploadLimits: {
    maxFileSizeBytes: number;
  };
  aiLimits: {
    maxTokensPerRequest: number;
  };
}

export default function SettingsPage() {
  const [data, setData] = useState<SettingsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        setLoading(true);
        const res = await api.get('/admin/settings');
        if (res.data?.success) {
          setData(res.data.data);
        }
      } catch (err) {
        toast.error('Failed to load settings');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchSettings();
  }, []);

  const handleSave = async () => {
    if (!data) return;
    try {
      setSaving(true);
      const res = await api.put('/admin/settings', data);
      if (res.data?.success) {
        toast.success('Settings saved successfully!');
      }
    } catch (err) {
      toast.error('Failed to save settings');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="flex flex-col items-center gap-2">
          <Loader2 size={40} className="animate-spin text-blue-600" />
          <span className="text-gray-500">Loading settings...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3">
        <SettingsIcon size={28} className="text-blue-600" />
        <div>
          <h1 className="text-3xl font-bold text-gray-900">System Settings</h1>
          <p className="text-gray-600">Configure system-wide settings and policies</p>
        </div>
      </div>

      {data && (
        <div className="space-y-6">
          {/* Security Settings */}
          <div className="bg-white rounded-lg border border-gray-200 p-6">
            <h2 className="text-lg font-bold text-gray-900 mb-4">Security Settings</h2>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Minimum Password Length</label>
                <input
                  type="number"
                  value={data.security.passwordMinLength}
                  onChange={(e) =>
                    setData({
                      ...data,
                      security: { ...data.security, passwordMinLength: parseInt(e.target.value) },
                    })
                  }
                  className="w-full bg-gray-50 border border-gray-300 rounded-lg px-4 py-2 text-sm focus:outline-none focus:border-blue-500"
                />
              </div>
              <div>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={data.security.requireSpecialChar}
                    onChange={(e) =>
                      setData({
                        ...data,
                        security: { ...data.security, requireSpecialChar: e.target.checked },
                      })
                    }
                    className="w-4 h-4 rounded border-gray-300"
                  />
                  <span className="text-sm font-semibold text-gray-700">Require Special Characters in Passwords</span>
                </label>
              </div>
              <div>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={data.security.requireNumbers}
                    onChange={(e) =>
                      setData({
                        ...data,
                        security: { ...data.security, requireNumbers: e.target.checked },
                      })
                    }
                    className="w-4 h-4 rounded border-gray-300"
                  />
                  <span className="text-sm font-semibold text-gray-700">Require Numbers in Passwords</span>
                </label>
              </div>
              <div>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={data.security.mfaEnabled}
                    onChange={(e) =>
                      setData({
                        ...data,
                        security: { ...data.security, mfaEnabled: e.target.checked },
                      })
                    }
                    className="w-4 h-4 rounded border-gray-300"
                  />
                  <span className="text-sm font-semibold text-gray-700">Enable Multi-Factor Authentication (MFA)</span>
                </label>
              </div>
            </div>
          </div>

          {/* Upload Settings */}
          <div className="bg-white rounded-lg border border-gray-200 p-6">
            <h2 className="text-lg font-bold text-gray-900 mb-4">Upload Settings</h2>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Maximum File Size (MB)</label>
              <input
                type="number"
                value={Math.round(data.uploadLimits.maxFileSizeBytes / (1024 * 1024))}
