          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 16, paddingTop: 12, borderTop: '1px solid var(--border)' }}>
            <TrendingUp size={12} color="#10B981" />
            <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
