                          borderRadius: 8
                        }}>
                          Score: {hQuiz.score} / {hQuiz.questions.length} ({percentScore}%)
                        </div>
                        <div style={{ fontSize: 12, color: 'var(--text-muted)', fontWeight: 500 }}>
                          Duration: {formatTime(hQuiz.timeTakenSeconds)}
                        </div>
