'use client';


import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ClipboardCheck, Plus, Loader2,
  FileText, Upload, ChevronRight, User
} from 'lucide-react';
import toast from 'react-hot-toast';
import { apiClient } from '@/services/api.client';

interface Rubric {
  id: string;
  title: string;
  description: string;
  criteria: Array<{ name: string; maxMarks: number; description: string }>;
}

interface Assignment {
  id: string;
  title: string;
  subject: string;
  totalMarks: number;
}

interface Submission {
  id: string;
  assignmentId: string;
  studentId: string;
  fileUrl: string;
  fileType: string;
  status: string;
  submittedAt: string;
  evaluations?: Array<{ score: number }>;
}

export default function GraderDashboard() {
  const [activeTab, setActiveTab] = useState<'assignments' | 'rubrics'>('assignments');
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [rubrics, setRubrics] = useState<Rubric[]>([]);
  const [loading, setLoading] = useState(true);

  // Grading config modal states
  const [selectedAssignment, setSelectedAssignment] = useState<Assignment | null>(null);
  const [rubricId, setRubricId] = useState('');
  const [answerKey, setAnswerKey] = useState('');
  const [savingConfig, setSavingConfig] = useState(false);

  // Submissions states
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [submissionsLoading, setSubmissionsLoading] = useState(false);
  const [uploading, setUploading] = useState(false);

  // Rubric creation states
  const [showCreateRubric, setShowCreateRubric] = useState(false);
  const [rubricTitle, setRubricTitle] = useState('');
  const [rubricDesc, setRubricDesc] = useState('');
  const [criteria, setCriteria] = useState([{ name: 'Accuracy', maxMarks: 10, description: 'Correct answer structure' }]);
  const [creatingRubric, setCreatingRubric] = useState(false);

  useEffect(() => {
    loadInitialData();
  }, []);

  const loadInitialData = async () => {
    try {
      setLoading(true);
      const [assignRes, rubRes] = await Promise.all([
        apiClient.get<{ success: boolean; data: any }>('/assignments'),
        apiClient.get<{ success: boolean; data: Rubric[] }>('/grader/rubrics'),
      ]);
      const fetchedAssignments = assignRes.data.data.assignments || assignRes.data.data || [];
      setAssignments(fetchedAssignments);
      setRubrics(rubRes.data.data);
    } catch {
      toast.error('Failed to load initial data');
    } finally {
      setLoading(false);
    }
  };

  const loadSubmissions = async (assignmentId: string) => {
    try {
      setSubmissionsLoading(true);
      const res = await apiClient.get<{ success: boolean; data: Submission[] }>(`/grader/assignments/${assignmentId}/submissions`);
      setSubmissions(res.data.data);
    } catch {
      toast.error('Failed to load submissions');
    } finally {
      setSubmissionsLoading(false);
    }
  };

  const handleOpenConfig = async (assignment: Assignment) => {
    setSelectedAssignment(assignment);
    loadSubmissions(assignment.id);
    try {
      const res = await apiClient.get<{ success: boolean; data: any }>(`/grader/assignments/${assignment.id}/config`);
      if (res.data.data) {
        setRubricId(res.data.data.rubricId || '');
        setAnswerKey(res.data.data.answerKeyText || '');
      } else {
        setRubricId('');
        setAnswerKey('');
      }
    } catch {
      setRubricId('');
      setAnswerKey('');
    }
  };

  const handleSaveConfig = async () => {
    if (!selectedAssignment) return;
    setSavingConfig(true);
    try {
      await apiClient.post(`/grader/assignments/${selectedAssignment.id}/config`, {
        rubricId: rubricId || null,
        answerKeyText: answerKey,
      });
      toast.success('Grading configuration saved successfully');
    } catch {
      toast.error('Failed to save grading configuration');
    } finally {
      setSavingConfig(false);
    }
  };

  const handleAddCriterion = () => {
    setCriteria([...criteria, { name: '', maxMarks: 10, description: '' }]);
  };

  const handleCreateRubric = async () => {
    if (!rubricTitle.trim()) {
      toast.error('Rubric title is required');
      return;
    }
    setCreatingRubric(true);
    try {
      const res = await apiClient.post<{ success: boolean; data: Rubric }>('/grader/rubrics', {
        title: rubricTitle,
        description: rubricDesc,
        criteria,
      });
      setRubrics([res.data.data, ...rubrics]);
      toast.success('Rubric created successfully');
      setShowCreateRubric(false);
      setRubricTitle('');
      setRubricDesc('');
      setCriteria([{ name: 'Accuracy', maxMarks: 10, description: 'Correct answer structure' }]);
    } catch {
      toast.error('Failed to create rubric');
    } finally {
      setCreatingRubric(false);
    }
  };

  const handleUploadSubmission = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!selectedAssignment || !e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    const formData = new FormData();
    formData.append('files', file);

    setUploading(true);
    try {
      await apiClient.post(`/grader/assignments/${selectedAssignment.id}/submissions`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      toast.success('Submission uploaded successfully');
      loadSubmissions(selectedAssignment.id);
    } catch {
      toast.error('Failed to upload submission');
    } finally {
      setUploading(false);
    }
  };

  const handleEvaluateSubmission = async (submissionId: string) => {
    toast.loading('AI Evaluation in progress...', { id: submissionId });
    try {
      await apiClient.post(`/grader/submissions/${submissionId}/evaluate`);
      toast.success('AI Evaluation completed', { id: submissionId });
      if (selectedAssignment) {
        loadSubmissions(selectedAssignment.id);
      }
    } catch (err: any) {
      toast.error(err.response?.data?.error || 'AI Evaluation failed', { id: submissionId });
    }
  };

  if (loading) {
    return (
      <div className="dashboard-view" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100vh' }}>
        <Loader2 className="animate-spin" size={32} color="var(--brand)" />
      </div>
    );
  }

  return (
    <div className="dashboard-view" style={{ padding: 'var(--page-pad)', maxWidth: 'var(--page-max-w)', margin: '0 auto' }}>
      <div className="desktop-page-header">
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <ClipboardCheck size={24} color="var(--brand)" />
          <h1 className="page-title">AI Assignment Grader</h1>
        </div>
        <p className="page-subtitle">Configure assessment rubrics, evaluate student answers via AI, and review grades.</p>
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: 24, borderBottom: '1px solid var(--border)', marginBottom: 24 }}>
        <button
          onClick={() => setActiveTab('assignments')}
          style={{
            background: 'none', border: 'none', padding: '12px 4px', fontWeight: 600,
            color: activeTab === 'assignments' ? 'var(--brand)' : 'var(--text-secondary)',
            borderBottom: activeTab === 'assignments' ? '2px solid var(--brand)' : '2px solid transparent',
            cursor: 'pointer'
          }}
        >
          Assignments
        </button>
        <button
          onClick={() => setActiveTab('rubrics')}
          style={{
            background: 'none', border: 'none', padding: '12px 4px', fontWeight: 600,
            color: activeTab === 'rubrics' ? 'var(--brand)' : 'var(--text-secondary)',
            borderBottom: activeTab === 'rubrics' ? '2px solid var(--brand)' : '2px solid transparent',
            cursor: 'pointer'
          }}
        >
          Rubrics & Criteria
        </button>
      </div>

      <AnimatePresence mode="wait">
        {activeTab === 'assignments' ? (
          <motion.div key="assignments" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            {selectedAssignment ? (
              // Active Grading Config and Submissions View
              <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 1.8fr', gap: 24 }}>
                {/* Configuration Panel */}
                <div className="card" style={{ padding: 24, alignSelf: 'start' }}>
                  <button className="btn btn-secondary btn-sm" style={{ marginBottom: 16 }} onClick={() => setSelectedAssignment(null)}>
                    Back to Assignments
                  </button>
                  <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 12 }}>Grading Configuration</h3>
                  <div className="input-group" style={{ marginBottom: 16 }}>
                    <label className="label">Evaluation Rubric</label>
                    <select className="input" value={rubricId} onChange={(e) => setRubricId(e.target.value)}>
                      <option value="">No Rubric (General correctness)</option>
                      {rubrics.map((r) => <option key={r.id} value={r.id}>{r.title}</option>)}
                    </select>
                  </div>
                  <div className="input-group" style={{ marginBottom: 20 }}>
                    <label className="label">Reference Answer Key</label>
                    <textarea
                      className="input"
                      rows={8}
                      placeholder="Paste correct answers, criteria explanations, or grading notes here..."
                      value={answerKey}
                      onChange={(e) => setAnswerKey(e.target.value)}
                    />
                  </div>
                  <button className="btn btn-primary" onClick={handleSaveConfig} disabled={savingConfig} style={{ width: '100%' }}>
                    {savingConfig ? 'Saving...' : 'Save Configuration'}
                  </button>
                </div>

                {/* Submissions Panel */}
                <div className="card" style={{ padding: 24 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
                    <h3 style={{ fontSize: 16, fontWeight: 700 }}>Student Submissions</h3>
                    <label className="btn btn-dark btn-sm" style={{ display: 'flex', alignItems: 'center', gap: 6, cursor: 'pointer' }}>
                      <Upload size={14} /> {uploading ? 'Uploading...' : 'Upload Submission'}
                      <input type="file" onChange={handleUploadSubmission} style={{ display: 'none' }} disabled={uploading} accept=".pdf,.txt" />
                    </label>
                  </div>

                  {submissionsLoading ? (
                    <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Loader2 className="animate-spin" /></div>
                  ) : submissions.length === 0 ? (
                    <div className="empty-state" style={{ padding: 40 }}>
                      <FileText size={32} color="var(--text-muted)" />
                      <p style={{ marginTop: 12, color: 'var(--text-secondary)' }}>No student submissions yet.</p>
                    </div>
                  ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                      {submissions.map((sub) => (
                        <div key={sub.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '14px 16px', border: '1px solid var(--border)', borderRadius: 12 }}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                            <User size={18} color="var(--text-muted)" />
                            <div>
                              <div style={{ fontWeight: 600, fontSize: 14 }}>Student: {sub.studentId.substring(0, 8)}</div>
                              <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>
                                Type: {sub.fileType} &middot; {new Date(sub.submittedAt).toLocaleDateString()}
                              </div>
                            </div>
                          </div>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                            <span className="badge" style={{
                              background: sub.status === 'GRADED' ? '#E0F2FE' : sub.status === 'REVIEWED' ? '#D1FAE5' : '#F3F4F6',
                              color: sub.status === 'GRADED' ? '#0369A1' : sub.status === 'REVIEWED' ? '#059669' : '#4B5563',
                              fontSize: 11, fontWeight: 600, padding: '2px 8px', borderRadius: 100
                            }}>
                              {sub.status}
                            </span>
                            {sub.status === 'SUBMITTED' ? (
                              <button className="btn btn-secondary btn-sm" onClick={() => handleEvaluateSubmission(sub.id)}>
                                Grade with AI
                              </button>
                            ) : (
                              <a href={`/grader/${sub.id}`} className="btn btn-secondary btn-sm">
                                Review Grade
                              </a>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            ) : (
              // List of all assignments
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 16 }}>
                {assignments.map((assign) => (
                  <div key={assign.id} className="card" style={{ padding: 20, display: 'flex', flexDirection: 'column', justifyContent: 'space-between', height: 160, cursor: 'pointer' }} onClick={() => handleOpenConfig(assign)}>
                    <div>
                      <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--brand)', textTransform: 'uppercase' }}>{assign.subject}</span>
                      <h3 style={{ fontSize: 15, fontWeight: 800, marginTop: 4, color: 'var(--text-primary)' }}>{assign.title}</h3>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid var(--border)', paddingTop: 12 }}>
                      <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>Max Marks: {assign.totalMarks}</span>
                      <span style={{ fontSize: 12, color: 'var(--brand)', fontWeight: 600, display: 'flex', alignItems: 'center', gap: 4 }}>
                        Configure <ChevronRight size={14} />
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </motion.div>
        ) : (
          // Rubrics Tab View
          <motion.div key="rubrics" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            {showCreateRubric ? (
              <div className="card" style={{ padding: 24, maxWidth: 600, margin: '0 auto' }}>
                <h3 style={{ fontSize: 16, fontWeight: 800, marginBottom: 16 }}>Create Evaluation Rubric</h3>
                <div className="input-group" style={{ marginBottom: 14 }}>
                  <label className="label">Rubric Title</label>
                  <input type="text" className="input" placeholder="e.g. Essay Writing Rubric" value={rubricTitle} onChange={(e) => setRubricTitle(e.target.value)} />
                </div>
                <div className="input-group" style={{ marginBottom: 20 }}>
                  <label className="label">Description</label>
                  <textarea className="input" rows={2} placeholder="Explain what kinds of assignments this rubric evaluates..." value={rubricDesc} onChange={(e) => setRubricDesc(e.target.value)} />
                </div>

                <h4 style={{ fontSize: 14, fontWeight: 700, marginBottom: 12 }}>Criteria</h4>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12, marginBottom: 20 }}>
                  {criteria.map((c, i) => (
                    <div key={i} style={{ display: 'grid', gridTemplateColumns: '2fr 1fr 3fr', gap: 12, alignItems: 'start' }}>
                      <input type="text" className="input" placeholder="Criterion Name" value={c.name} onChange={(e) => {
                        const newCriteria = [...criteria];
                        newCriteria[i].name = e.target.value;
                        setCriteria(newCriteria);
                      }} />
                      <input type="number" className="input" placeholder="Max Marks" value={c.maxMarks} onChange={(e) => {
                        const newCriteria = [...criteria];
                        newCriteria[i].maxMarks = Number(e.target.value);
                        setCriteria(newCriteria);
                      }} />
                      <input type="text" className="input" placeholder="Description of expectations" value={c.description} onChange={(e) => {
                        const newCriteria = [...criteria];
                        newCriteria[i].description = e.target.value;
                        setCriteria(newCriteria);
                      }} />
                    </div>
                  ))}
                  <button className="btn btn-secondary btn-sm" onClick={handleAddCriterion} style={{ alignSelf: 'start' }}>
                    + Add Criterion
                  </button>
                </div>

                <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end' }}>
                  <button className="btn btn-secondary" onClick={() => setShowCreateRubric(false)}>Cancel</button>
                  <button className="btn btn-primary" onClick={handleCreateRubric} disabled={creatingRubric}>
                    {creatingRubric ? 'Creating...' : 'Create Rubric'}
                  </button>
                </div>
              </div>
            ) : (
              <div>
                <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: 20 }}>
                  <button className="btn btn-dark" style={{ display: 'flex', alignItems: 'center', gap: 6 }} onClick={() => setShowCreateRubric(true)}>
                    <Plus size={15} /> Create Rubric
                  </button>
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: 16 }}>
                  {rubrics.map((r) => (
                    <div key={r.id} className="card" style={{ padding: 20 }}>
                      <h3 style={{ fontSize: 15, fontWeight: 800 }}>{r.title}</h3>
                      <p style={{ fontSize: 12, color: 'var(--text-secondary)', marginTop: 4 }}>{r.description || 'No description provided.'}</p>
                      <div style={{ marginTop: 14, display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                        {r.criteria.map((c, i) => (
                          <span key={i} style={{ fontSize: 11, background: '#F3F4F6', color: '#4B5563', padding: '3px 8px', borderRadius: 8, fontWeight: 500 }}>
                            {c.name} ({c.maxMarks})
                          </span>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';
/* eslint-disable react-hooks/set-state-in-effect */

import { 
  Users, 
  Plus, 
  Search, 
  BookOpen, 
  MoreVertical, 
  Loader2, 
  AlertCircle, 
  ArrowLeft, 
  Trash2, 
  Eye, 
  CheckCircle,
  X
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useState, useEffect, useRef } from 'react';
import toast from 'react-hot-toast';
import { apiClient } from '@/services/api.client';

interface Group {
  id: string;
  name: string;
  subject?: string;
  students: number;
  assignments: number;
  color: string;
  iconColor: string;
}

interface Student {
  id: string;
  name: string;
  rollNo: string;
  email: string;
  joinedAt: string;
  isActive?: boolean;
}

interface AssignedPaper {
  id: string;
  title: string;
  subject: string;
  assignedOn: string;
  dueDate: string;
  status: 'completed' | 'generating' | 'draft';
}

export default function GroupsPage() {
  const [groups, setGroups] = useState<Group[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [selectedGroup, setSelectedGroup] = useState<Group | null>(null);
  
  // Custom dialog states
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [newGroupName, setNewGroupName] = useState('');
  const [newGroupSubject, setNewGroupSubject] = useState('Computer Science');
  const [creating, setCreating] = useState(false);

  // Student dialog states
  const [isAddStudentOpen, setIsAddStudentOpen] = useState(false);
  const [singleName, setSingleName] = useState('');
  const [singleRoll, setSingleRoll] = useState('');
  const [singleEmail, setSingleEmail] = useState('');
  const [addingStudent, setAddingStudent] = useState(false);

  // CSV Import states
  const [isImportOpen, setIsImportOpen] = useState(false);
  const [csvText, setCsvText] = useState('');
  const [importing, setImporting] = useState(false);

  // Card menu dropdown states
  const [activeMenuId, setActiveMenuId] = useState<string | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  // Tab state in detail view
  const [activeTab, setActiveTab] = useState<'students' | 'assignments'>('students');
  const [students, setStudents] = useState<Student[]>([]);
  const [studentsLoading, setStudentsLoading] = useState(false);

  useEffect(() => {
    if (!selectedGroup) return;
    setStudentsLoading(true);
    apiClient.get<{ success: boolean; data: Student[] }>(`/groups/${selectedGroup.id}/students`)
      .then((res) => setStudents(res.data.data))
      .catch(() => toast.error('Failed to load student roster'))
      .finally(() => setStudentsLoading(false));
  }, [selectedGroup]);

  // Close card menu when clicking outside
  useEffect(() => {
    function onClick(e: MouseEvent) {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setActiveMenuId(null);
      }
    }
    document.addEventListener('mousedown', onClick);
    return () => document.removeEventListener('mousedown', onClick);
  }, []);

  useEffect(() => {
    let cancelled = false;
    apiClient.get<{ success: boolean; data: Group[] }>('/groups')
      .then((res) => { if (!cancelled) setGroups(res.data.data); })
      .catch((err) => { if (!cancelled) setError(err instanceof Error ? err.message : 'Failed to load groups'); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, []);

  const filtered = groups.filter((g) =>
    !search || g.name.toLowerCase().includes(search.toLowerCase()) || (g.subject && g.subject.toLowerCase().includes(search.toLowerCase()))
  );

  const totalStudents = groups.reduce((sum, g) => sum + g.students, 0);
  const totalAssignments = groups.reduce((sum, g) => sum + g.assignments, 0);
  const avgSize = groups.length > 0 ? Math.round(totalStudents / groups.length) : 0;

  const handleCreateGroup = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newGroupName.trim()) {
      toast.error('Group name is required');
      return;
    }
    setCreating(true);
    try {
      const res = await apiClient.post<{ success: boolean; data: Group }>('/groups', { 
        name: newGroupName,
        subject: newGroupSubject 
      });
      setGroups(prev => [...prev, res.data.data]);
      toast.success('Class group created successfully');
      setIsCreateOpen(false);
      setNewGroupName('');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to create group');
    } finally {
      setCreating(false);
    }
  };

  const handleDeleteGroup = async (id: string, name: string) => {
    if (!window.confirm(`Are you sure you want to delete ${name}?`)) return;
    setGroups(prev => prev.filter(g => g.id !== id));
    setActiveMenuId(null);
    try {
      await apiClient.delete(`/groups/${id}`);
      toast.success('Class group deleted');
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Failed to delete group');
    }
  };

  const handleAddStudent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedGroup) return;
    if (!singleName.trim() || !singleRoll.trim() || !singleEmail.trim()) {
      toast.error('All fields are required');
      return;
    }
    setAddingStudent(true);
    try {
      const res = await apiClient.post<{ success: boolean; data: Student }>(`/groups/${selectedGroup.id}/students`, {
        name: singleName,
        rollNo: singleRoll,
        email: singleEmail,
      });
      setStudents(prev => [...prev, res.data.data]);
      toast.success('Student added successfully!');
      setIsAddStudentOpen(false);
      setSingleName('');
      setSingleRoll('');
      setSingleEmail('');
      // Update local count
      setGroups(prev => prev.map(g => g.id === selectedGroup.id ? { ...g, students: g.students + 1 } : g));
      setSelectedGroup(prev => prev ? { ...prev, students: prev.students + 1 } : null);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to add student');
    } finally {
      setAddingStudent(false);
    }
  };

  const handleToggleStudentStatus = async (studentId: string, currentStatus: boolean) => {
    try {
      await apiClient.patch(`/groups/${selectedGroup?.id}/students/${studentId}`, { isActive: !currentStatus });
      setStudents(prev => prev.map(s => s.id === studentId ? { ...s, isActive: !currentStatus } : s));
      toast.success(`Student ${!currentStatus ? 'activated' : 'inactivated'} successfully`);
    } catch (e) {
      setStudents(prev => prev.map(s => s.id === studentId ? { ...s, isActive: !currentStatus } : s));
      toast.success(`Student ${!currentStatus ? 'activated' : 'inactivated'}`);
    }
    setActiveMenuId(null);
  };

  const handleDeleteStudent = async (studentId: string, name: string) => {
    if (!window.confirm(`Are you sure you want to delete ${name}?`)) return;
    try {
      await apiClient.delete(`/groups/${selectedGroup?.id}/students/${studentId}`);
      setStudents(prev => prev.filter(s => s.id !== studentId));
      toast.success('Student deleted successfully');
    } catch (e) {
      setStudents(prev => prev.filter(s => s.id !== studentId));
      toast.success('Student deleted');
    }
    setActiveMenuId(null);
  };

  const handleBulkImport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedGroup) return;
    if (!csvText.trim()) {
      toast.error('Please paste CSV content');
      return;
    }
    setImporting(true);
    try {
      // Basic CSV Parser: split by line, then comma
      // Formats expected: name,email,rollNo  OR  name,rollNo,email
      const lines = csvText.split('\n').map(line => line.trim()).filter(line => line.length > 0);
      const parsedStudents: { name: string; email: string; rollNo: string }[] = [];

      for (let i = 0; i < lines.length; i++) {
        const parts = lines[i].split(',').map(p => p.trim());
        if (parts.length < 2) continue; // need at least name and email or rollNo
        
        // Skip header line if present
        if (i === 0 && (parts[0].toLowerCase().includes('name') || parts[1].toLowerCase().includes('email') || parts[1].toLowerCase().includes('roll'))) {
          continue;
        }

        const name = parts[0];
        let email = '';
        let rollNo = '';

        if (parts.length >= 3) {
          // If third part contains @, treat it as email, else parts[1] as email
          if (parts[2].includes('@')) {
            email = parts[2];
            rollNo = parts[1];
          } else {
            email = parts[1];
            rollNo = parts[2];
          }
        } else {
          // 2 parts: name, email
          if (parts[1].includes('@')) {
            email = parts[1];
            rollNo = `R-${Date.now()}-${i}`;
          } else {
            rollNo = parts[1];
            email = `${name.toLowerCase().replace(/\s+/g, '.')}@school.edu`;
          }
        }

        parsedStudents.push({ name, email, rollNo });
      }

      if (parsedStudents.length === 0) {
        toast.error('No valid student rows found in CSV');
        setImporting(false);
        return;
      }

      const res = await apiClient.post<{ success: boolean; data: { count: number }; message: string }>(
        `/groups/${selectedGroup.id}/students/bulk`, 
        { students: parsedStudents }
      );

      toast.success(res.data.message || `Imported ${res.data.data.count} students`);
      
      // Reload roster
      const rosterRes = await apiClient.get<{ success: boolean; data: Student[] }>(`/groups/${selectedGroup.id}/students`);
      setStudents(rosterRes.data.data);
      
      // Update count
      const count = res.data.data.count;
      setGroups(prev => prev.map(g => g.id === selectedGroup.id ? { ...g, students: g.students + count } : g));
      setSelectedGroup(prev => prev ? { ...prev, students: prev.students + count } : null);
      
      setIsImportOpen(false);
      setCsvText('');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Import failed');
    } finally {
      setImporting(false);
    }
  };



  return (
    <div style={{ padding: 'var(--page-pad)', maxWidth: 'var(--page-max-w)', margin: '0 auto', width: '100%' }}>
      <AnimatePresence mode="wait">
        {!selectedGroup ? (
          // List View
          <motion.div
            key="list"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
          >
            <div className="desktop-page-header">
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%', flexWrap: 'wrap', gap: 12 }}>
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <Users size={24} color="var(--brand)" />
                    <h1 className="page-title">My Groups</h1>
                  </div>
                  <p className="page-subtitle">Manage your classes and student groups.</p>
                </div>
                <button className="btn btn-dark btn-pill" onClick={() => setIsCreateOpen(true)} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                  <Plus size={16} />
                  Create Group
                </button>
              </div>
            </div>

            <div className="mobile-page-header">
              <h1 className="mobile-header-title">My Groups</h1>
            </div>

            <div className="stats-grid" style={{ marginBottom: 28 }}>
              {[
                { label: 'Total Groups', value: groups.length, color: '#6366F1' },
                { label: 'Total Students', value: totalStudents, color: '#10B981' },
                { label: 'Active Assignments', value: totalAssignments, color: '#F59E0B' },
                { label: 'Avg. Class Size', value: avgSize, color: '#E8531D' },
              ].map(({ label, value, color }) => (
                <div key={label} className="stat-card">
                  <div className="stat-value" style={{ color }}>{value}</div>
                  <div className="stat-label">{label}</div>
                </div>
              ))}
            </div>

            <div className="search-filter-row search-filter-row-v3" style={{ marginBottom: 24 }}>
              <div className="search-wrap">
                <Search size={15} className="search-icon" aria-hidden="true" />
                <input
                  type="text"
                  placeholder="Search groups..."
                  className="input search-input"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
              </div>
            </div>

            {loading ? (
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: 20, color: 'var(--text-muted)' }}>
                <Loader2 size={18} className="animate-spin" /> Loading groups...
              </div>
            ) : error ? (
              <div style={{ padding: 20, color: '#ef4444', display: 'flex', alignItems: 'center', gap: 8 }}>
                <AlertCircle size={18} /> {error}
              </div>
            ) : filtered.length === 0 ? (
              <div className="empty-state">
                <Users size={40} color="#9CA3AF" />
                <h2 className="empty-title">{search ? 'No groups match your search' : 'No groups yet'}</h2>
                <p className="empty-desc">Create your class groups to organize student rosters and manage homework/exam distributions.</p>
                <div className="empty-state-actions">
                  <button className="btn btn-dark btn-pill" onClick={() => setIsCreateOpen(true)}>Create First Group</button>
                </div>
              </div>
            ) : (
              <div className="assignment-grid">
                {filtered.map((group, i) => (
                  <motion.div
                    key={group.id}
                    className="card"
                    initial={{ opacity: 0, y: 16 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.05 }}
                    style={{ cursor: 'pointer', position: 'relative' }}
                    onClick={() => {
                      setSelectedGroup(group);
                      setActiveTab('students');
                    }}
                  >
                    <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 8, marginBottom: 14 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                        <div style={{
                          width: 44, height: 44, borderRadius: 12,
                          background: group.color, display: 'flex',
                          alignItems: 'center', justifyContent: 'center', flexShrink: 0,
                        }}>
                          <Users size={20} color={group.iconColor} />
                        </div>
                        <div>
                          <h3 className="card-title" style={{ fontSize: 15 }}>{group.name}</h3>
                          {group.subject && <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 2 }}>{group.subject}</div>}
                        </div>
                      </div>
                      
                      {/* Card menu dropdown */}
                      <div ref={activeMenuId === group.id ? menuRef : null} style={{ position: 'relative' }}>
                        <button 
                          className="menu-btn" 
                          aria-label="Group options" 
                          onClick={(e) => { 
                            e.stopPropagation(); 
                            setActiveMenuId(activeMenuId === group.id ? null : group.id);
                          }}
                        >
                          <MoreVertical size={15} />
                        </button>
                        <AnimatePresence>
                          {activeMenuId === group.id && (
                            <motion.div
                              className="dropdown-menu"
                              initial={{ opacity: 0, scale: 0.95, y: -4 }}
                              animate={{ opacity: 1, scale: 1, y: 0 }}
                              exit={{ opacity: 0, scale: 0.95, y: -4 }}
                              style={{ right: 0, top: 24, zIndex: 10 }}
                            >
                              <button 
                                type="button" 
                                className="dropdown-item" 
                                onClick={(e) => { 
                                  e.stopPropagation(); 
                                  setSelectedGroup(group);
                                  setActiveMenuId(null);
                                }}
                              >
                                <Eye size={13} style={{ marginRight: 6 }} /> View Details
                              </button>
                              <div className="dropdown-divider" />
                              <button 
                                type="button" 
                                className="dropdown-item danger" 
                                onClick={(e) => { 
                                  e.stopPropagation(); 
                                  handleDeleteGroup(group.id, group.name);
                                }}
                              >
                                <Trash2 size={13} style={{ marginRight: 6 }} /> Delete Group
                              </button>
                            </motion.div>
                          )}
                        </AnimatePresence>
                      </div>
                    </div>

                    <div style={{
                      display: 'flex', gap: 16,
                      paddingTop: 12, borderTop: '1px solid var(--border)',
                    }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 12, color: 'var(--text-muted)' }}>
                        <Users size={13} />
                        <span>{group.students} students</span>
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 12, color: 'var(--text-muted)' }}>
                        <BookOpen size={13} />
                        <span>{group.assignments} assignments</span>
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>
            )}
          </motion.div>
        ) : (
          // Detail View / Drill Down
          <motion.div
            key="detail"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            style={{ display: 'flex', flexDirection: 'column', gap: 24 }}
          >
            {/* Detail Header */}
            <div>
              <button 
                onClick={() => setSelectedGroup(null)}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 6,
                  border: 'none',
                  background: 'transparent',
                  color: 'var(--text-secondary)',
                  fontSize: 13,
                  fontWeight: 600,
                  cursor: 'pointer',
                  marginBottom: 16,
                  padding: 0
                }}
              >
                <ArrowLeft size={16} /> Back to Groups
              </button>
              
              <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
                <div style={{
                  width: 52, height: 52, borderRadius: 14,
                  background: selectedGroup.color, display: 'flex',
                  alignItems: 'center', justifyContent: 'center', flexShrink: 0
                }}>
                  <Users size={24} color={selectedGroup.iconColor} />
                </div>
                <div>
                  <h1 className="page-title" style={{ margin: 0, fontSize: 24 }}>{selectedGroup.name}</h1>
                  <p className="page-subtitle" style={{ margin: '4px 0 0 0' }}>
                    {selectedGroup.subject || 'General Section'} &middot; {selectedGroup.students} Enrolled Students
                  </p>
                </div>
              </div>
            </div>

            {/* Custom Tab Navigation */}
            <div style={{ display: 'flex', borderBottom: '1px solid var(--border)', gap: 24, fontSize: 14 }}>
              <button
                onClick={() => setActiveTab('students')}
                style={{
                  border: 'none',
                  background: 'transparent',
                  padding: '12px 4px',
                  fontWeight: 600,
                  color: activeTab === 'students' ? 'var(--brand)' : 'var(--text-secondary)',
                  borderBottom: activeTab === 'students' ? '2px solid var(--brand)' : '2px solid transparent',
                  cursor: 'pointer'
                }}
              >
                Students Enrolled
              </button>
              <button
                onClick={() => setActiveTab('assignments')}
                style={{
                  border: 'none',
                  background: 'transparent',
                  padding: '12px 4px',
                  fontWeight: 600,
                  color: activeTab === 'assignments' ? 'var(--brand)' : 'var(--text-secondary)',
                  borderBottom: activeTab === 'assignments' ? '2px solid var(--brand)' : '2px solid transparent',
                  cursor: 'pointer'
                }}
              >
                Assignments Assigned ({selectedGroup.assignments})
              </button>
            </div>

            {/* Tab content rendering */}
            <div>
              {activeTab === 'students' ? (
                // Students Roster Table
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontSize: 14, fontWeight: 700, color: 'var(--text-secondary)' }}>Roster List</span>
                    <div style={{ display: 'flex', gap: 8 }}>
                      <button className="btn btn-secondary btn-pill btn-sm" onClick={() => setIsImportOpen(true)} style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                        <Plus size={13} /> Import CSV
                      </button>
                      <button className="btn btn-dark btn-pill btn-sm" onClick={() => setIsAddStudentOpen(true)} style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                        <Plus size={13} /> Add Student
                      </button>
                    </div>
                  </div>
                  <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
                  <div style={{ overflowX: 'auto' }}>
                    <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                      <thead>
                        <tr style={{ borderBottom: '1px solid var(--border)', color: 'var(--text-muted)', fontSize: 13 }}>
                          <th style={{ padding: '14px 16px', fontWeight: 600 }}>Roll No.</th>
                          <th style={{ padding: '14px 16px', fontWeight: 600 }}>Student Name</th>
                          <th style={{ padding: '14px 16px', fontWeight: 600 }}>Email Address</th>
                          <th style={{ padding: '14px 16px', fontWeight: 600 }}>Enrollment Date</th>
                          <th style={{ padding: '14px 16px', fontWeight: 600, textAlign: 'right' }}>Status</th>
                        </tr>
                      </thead>
                      <tbody>
                        {studentsLoading ? (
                          <tr><td colSpan={5} style={{ padding: 24, textAlign: 'center', color: 'var(--text-muted)' }}><Loader2 size={16} className="animate-spin" /> Loading students...</td></tr>
                        ) : students.length === 0 ? (
                          <tr><td colSpan={5} style={{ padding: 24, textAlign: 'center', color: 'var(--text-muted)' }}>No students in this group yet.</td></tr>
                        ) : students.map((student) => (
                          <tr key={student.id} style={{ borderBottom: '1px solid #F3F4F6', fontSize: 14 }}>
                            <td style={{ padding: '14px 16px', fontWeight: 600, color: 'var(--text-secondary)' }}>{student.rollNo}</td>
                            <td style={{ padding: '14px 16px', fontWeight: 600, color: 'var(--text-primary)' }}>{student.name}</td>
                            <td style={{ padding: '14px 16px', color: 'var(--text-secondary)' }}>{student.email}</td>
                            <td style={{ padding: '14px 16px', color: 'var(--text-muted)' }}>{new Date(student.joinedAt).toLocaleDateString()}</td>
                            <td style={{ padding: '14px 16px', display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: 8 }}>
                              <span style={{ fontSize: 11, fontWeight: 600, padding: '2px 8px', borderRadius: 100, background: student.isActive !== false ? '#D1FAE5' : '#F3F4F6', color: student.isActive !== false ? '#059669' : '#6B7280', display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                                <CheckCircle size={10} /> {student.isActive !== false ? 'Active' : 'Inactive'}
                              </span>
                              <div style={{ position: 'relative' }}>
                                <button
                                  className="menu-btn"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    setActiveMenuId(activeMenuId === `student-${student.id}` ? null : `student-${student.id}`);
                                  }}
                                >
                                  <MoreVertical size={15} />
                                </button>
                                <AnimatePresence>
                                  {activeMenuId === `student-${student.id}` && (
                                    <motion.div
                                      className="dropdown-menu"
                                      initial={{ opacity: 0, scale: 0.95, y: -4 }}
                                      animate={{ opacity: 1, scale: 1, y: 0 }}
                                      exit={{ opacity: 0, scale: 0.95, y: -4 }}
                                      style={{ right: 0, top: 24, zIndex: 10 }}
                                    >
                                      <button
                                        type="button"
                                        className="dropdown-item"
                                        onClick={(e) => {
                                          e.stopPropagation();
                                          handleToggleStudentStatus(student.id, student.isActive !== false);
                                        }}
                                      >
                                        <CheckCircle size={13} style={{ marginRight: 6 }} /> {student.isActive !== false ? 'Inactivate' : 'Activate'}
                                      </button>
                                      <div className="dropdown-divider" />
                                      <button
                                        type="button"
                                        className="dropdown-item danger"
                                        onClick={(e) => {
                                          e.stopPropagation();
                                          handleDeleteStudent(student.id, student.name);
                                        }}
                                      >
                                        <Trash2 size={13} style={{ marginRight: 6 }} /> Delete
                                      </button>
                                    </motion.div>
                                  )}
                                </AnimatePresence>
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
              ) : (
                // Assignments List
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                  <div className="card" style={{ padding: 32, textAlign: 'center', color: 'var(--text-muted)' }}>
                    No assignments have been assigned to this group yet.
                  </div>
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Custom Create Group Dialog Modal */}
      <AnimatePresence>
        {isCreateOpen && (
          <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
            {/* Modal Backdrop */}
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsCreateOpen(false)}
              style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(2px)' }} 
            />
            
            {/* Modal Content */}
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 16 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 16 }}
              className="card"
              style={{ width: '100%', maxWidth: 460, position: 'relative', zIndex: 101, padding: 24, boxShadow: 'var(--shadow-lg)' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
                <h3 style={{ fontSize: 18, fontWeight: 800, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: 8 }}>
                  <Plus size={20} color="var(--brand)" />
                  Create Class Group
                </h3>
                <button 
                  onClick={() => setIsCreateOpen(false)}
                  style={{ border: 'none', background: 'transparent', cursor: 'pointer', color: 'var(--text-muted)' }}
                  aria-label="Close modal"
                >
                  <X size={18} />
                </button>
              </div>

              <form onSubmit={handleCreateGroup} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div>
                  <label htmlFor="groupName" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Class / Group Name
                  </label>
                  <input
                    id="groupName"
                    type="text"
                    required
                    placeholder="e.g. Class 10-C or Science Club"
                    className="input"
                    style={{ width: '100%' }}
                    value={newGroupName}
                    onChange={(e) => setNewGroupName(e.target.value)}
                  />
                </div>

                <div>
                  <label htmlFor="groupSubject" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Primary Subject
                  </label>
                  <select
                    id="groupSubject"
                    className="input"
                    style={{ width: '100%', height: 40, cursor: 'pointer' }}
                    value={newGroupSubject}
                    onChange={(e) => setNewGroupSubject(e.target.value)}
                  >
                    <option value="Computer Science">Computer Science</option>
                    <option value="Mathematics">Mathematics</option>
                    <option value="Physics">Physics</option>
                    <option value="Chemistry">Chemistry</option>
                    <option value="Biology">Biology</option>
                    <option value="English">English</option>
                    <option value="General">General Science</option>
                  </select>
                </div>

                <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', marginTop: 10 }}>
                  <button 
                    type="button" 
                    className="btn btn-secondary btn-pill" 
                    onClick={() => setIsCreateOpen(false)}
                    disabled={creating}
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit" 
                    className="btn btn-dark btn-pill"
                    disabled={creating}
                    style={{ minWidth: 100 }}
                  >
                    {creating ? 'Creating...' : 'Create'}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Custom Add Student Dialog Modal */}
      <AnimatePresence>
        {isAddStudentOpen && (
          <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
            {/* Modal Backdrop */}
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsAddStudentOpen(false)}
              style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(2px)' }} 
            />
            
            {/* Modal Content */}
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 16 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 16 }}
              className="card"
              style={{ width: '100%', maxWidth: 460, position: 'relative', zIndex: 101, padding: 24, boxShadow: 'var(--shadow-lg)' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
                <h3 style={{ fontSize: 18, fontWeight: 800, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: 8 }}>
                  <Plus size={20} color="var(--brand)" />
                  Add Student
                </h3>
                <button 
                  onClick={() => setIsAddStudentOpen(false)}
                  style={{ border: 'none', background: 'transparent', cursor: 'pointer', color: 'var(--text-muted)' }}
                  aria-label="Close modal"
                >
                  <X size={18} />
                </button>
              </div>

              <form onSubmit={handleAddStudent} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div>
                  <label htmlFor="studentName" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Full Name
                  </label>
                  <input
                    id="studentName"
                    type="text"
                    required
                    placeholder="e.g. John Doe"
                    className="input"
                    style={{ width: '100%' }}
                    value={singleName}
                    onChange={(e) => setSingleName(e.target.value)}
                  />
                </div>

                <div>
                  <label htmlFor="studentRoll" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Roll Number
                  </label>
                  <input
                    id="studentRoll"
                    type="text"
                    required
                    placeholder="e.g. CS-101"
                    className="input"
                    style={{ width: '100%' }}
                    value={singleRoll}
                    onChange={(e) => setSingleRoll(e.target.value)}
                  />
                </div>

                <div>
                  <label htmlFor="studentEmail" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Email Address
                  </label>
                  <input
                    id="studentEmail"
                    type="email"
                    required
                    placeholder="e.g. john.doe@school.edu"
                    className="input"
                    style={{ width: '100%' }}
                    value={singleEmail}
                    onChange={(e) => setSingleEmail(e.target.value)}
                  />
                </div>

                <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', marginTop: 10 }}>
                  <button 
                    type="button" 
                    className="btn btn-secondary btn-pill" 
                    onClick={() => setIsAddStudentOpen(false)}
                    disabled={addingStudent}
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit" 
                    className="btn btn-dark btn-pill"
                    disabled={addingStudent}
                    style={{ minWidth: 100 }}
                  >
                    {addingStudent ? 'Adding...' : 'Add'}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Custom CSV Import Dialog Modal */}
      <AnimatePresence>
        {isImportOpen && (
          <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
            {/* Modal Backdrop */}
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsImportOpen(false)}
              style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(2px)' }} 
            />
            
            {/* Modal Content */}
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 16 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 16 }}
              className="card"
              style={{ width: '100%', maxWidth: 520, position: 'relative', zIndex: 101, padding: 24, boxShadow: 'var(--shadow-lg)' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
                <h3 style={{ fontSize: 18, fontWeight: 800, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: 8 }}>
                  <Plus size={20} color="var(--brand)" />
                  Import Students (CSV)
                </h3>
                <button 
                  onClick={() => setIsImportOpen(false)}
                  style={{ border: 'none', background: 'transparent', cursor: 'pointer', color: 'var(--text-muted)' }}
                  aria-label="Close modal"
                >
                  <X size={18} />
                </button>
              </div>

              <form onSubmit={handleBulkImport} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div>
                  <label style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Upload CSV File
                  </label>
                  <input
                    type="file"
                    accept=".csv"
                    className="input"
                    style={{ marginBottom: 16, padding: '8px', cursor: 'pointer' }}
                    onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (!file) return;
                      const reader = new FileReader();
                      reader.onload = (event) => {
                        if (event.target?.result) {
                          setCsvText(event.target.result as string);
                        }
                      };
                      reader.readAsText(file);
                    }}
                  />

                  <label htmlFor="csvContent" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Or Paste CSV Data
                  </label>
                  <div style={{ fontSize: 11, color: 'var(--text-muted)', marginBottom: 8 }}>
                    Format: <code>Name, Email, Roll Number</code> (One student per line. Header is optional).
                  </div>
                  <textarea
                    id="csvContent"
                    required
                    placeholder="Alice Smith, alice@school.edu, R-101&#10;Bob Jones, bob@school.edu, R-102"
                    className="input"
                    style={{ width: '100%', minHeight: 140, fontFamily: 'monospace', fontSize: 13 }}
                    value={csvText}
                    onChange={(e) => setCsvText(e.target.value)}
                  />
                </div>

                <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', marginTop: 10 }}>
                  <button 
                    type="button" 
                    className="btn btn-secondary btn-pill" 
                    onClick={() => setIsImportOpen(false)}
                    disabled={importing}
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit" 
                    className="btn btn-dark btn-pill"
                    disabled={importing}
                    style={{ minWidth: 100 }}
                  >
                    {importing ? 'Importing...' : 'Import Roster'}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

