                          </td>
                          <td style={{ padding: 12, color: 'var(--text-secondary)' }}>{q.bloomLevel}</td>
                          <td style={{ padding: 12, textAlign: 'center' }}>
                            <button 
                              className="btn btn-secondary btn-sm"
