        )}
      </AnimatePresence>

      {/* Question Details / Versions Modal */}
      <AnimatePresence>
        {selectedQuestion && (
          <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setSelectedQuestion(null)}
              style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(2px)' }} 
            />

            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 16 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 16 }}
              className="card"
              style={{ width: '100%', maxWidth: 700, position: 'relative', zIndex: 101, padding: 24, maxHeight: '85vh', overflowY: 'auto' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
                <h3 style={{ fontSize: 18, fontWeight: 800 }}>
                  Question Details
                </h3>
                <button onClick={() => setSelectedQuestion(null)} style={{ border: 'none', background: 'transparent', cursor: 'pointer', color: 'var(--text-muted)' }}>
                  <X size={18} />
                </button>
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
                    <label style={{ fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)' }}>Question Content</label>
                    {!isEditing && (
                      <button className="btn btn-secondary btn-sm" onClick={() => setIsEditing(true)} style={{ padding: '2px 8px', fontSize: 12 }}>
                        <Edit3 size={12} style={{ marginRight: 4 }} /> Edit
                      </button>
                    )}
                  </div>

                  {isEditing ? (
                    <textarea
                      className="input"
                      style={{ width: '100%', minHeight: 80, fontFamily: 'monospace' }}
                      value={editContent}
                      onChange={(e) => setEditContent(e.target.value)}
                    />
                  ) : (
                    <div style={{ padding: 12, background: 'var(--bg-secondary)', borderRadius: 6, fontFamily: 'monospace', whiteSpace: 'pre-wrap' }}>
                      {selectedQuestion.content}
                    </div>
                  )}
                </div>

                <div>
                  <label style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>Correct Answer</label>
                  {isEditing ? (
                    <input
                      type="text"
                      className="input"
                      style={{ width: '100%' }}
                      value={editAnswer}
                      onChange={(e) => setEditAnswer(e.target.value)}
                    />
                  ) : (
                    <div style={{ padding: 10, background: 'var(--bg-secondary)', borderRadius: 6 }}>
                      {selectedQuestion.answer || <em style={{ color: 'var(--text-muted)' }}>No answer key specified</em>}
                    </div>
                  )}
                </div>

                {isEditing && (
                  <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
                    <button className="btn btn-secondary btn-pill btn-sm" onClick={() => setIsEditing(false)}>Cancel</button>
                    <button className="btn btn-dark btn-pill btn-sm" onClick={handleUpdateQuestion}>Save Changes</button>
                  </div>
                )}

                <div style={{ borderTop: '1px solid var(--border)', paddingTop: 16 }}>
                  <h4 style={{ fontSize: 14, fontWeight: 700, display: 'flex', alignItems: 'center', gap: 6, marginBottom: 12 }}>
                    <History size={16} /> Version History
                  </h4>
                  {loadingVersions ? (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, color: 'var(--text-muted)' }}>
                      <Loader2 size={14} className="animate-spin" /> Loading versions...
                    </div>
                  ) : questionVersions.length === 0 ? (
                    <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>No previous versions found.</div>
                  ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                      {questionVersions.map((v) => (
                        <div key={v.id} style={{ border: '1px solid var(--border)', borderRadius: 6, padding: 10, fontSize: 13 }}>
                          <div style={{ display: 'flex', justifyContent: 'space-between', color: 'var(--text-muted)', fontSize: 11, marginBottom: 4 }}>
                            <span>Version #{v.versionNumber} by {v.updatedBy}</span>
                            <span>{new Date(v.createdAt).toLocaleString()}</span>
                          </div>
                          <div style={{ fontFamily: 'monospace', background: 'var(--bg-secondary)', padding: 6, borderRadius: 4, marginTop: 4 }}>
                            {v.content}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Create Collection Dialog Modal */}
      <AnimatePresence>
        {isCreateCollectionOpen && (
          <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsCreateCollectionOpen(false)}
              style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(2px)' }} 
            />

            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 16 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 16 }}
              className="card"
              style={{ width: '100%', maxWidth: 460, position: 'relative', zIndex: 101, padding: 24 }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
                <h3 style={{ fontSize: 18, fontWeight: 800 }}>
                  Create New Collection
                </h3>
                <button onClick={() => setIsCreateCollectionOpen(false)} style={{ border: 'none', background: 'transparent', cursor: 'pointer', color: 'var(--text-muted)' }}>
                  <X size={18} />
                </button>
              </div>

              <form onSubmit={handleCreateCollection} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div>
                  <label htmlFor="collName" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Collection Name
                  </label>
                  <input
                    id="collName"
                    type="text"
                    required
                    placeholder="e.g. Midterm Pool 2026 or Final Review"
                    className="input"
                    style={{ width: '100%' }}
                    value={newCollName}
                    onChange={(e) => setNewCollName(e.target.value)}
                  />
                </div>

                <div>
                  <label htmlFor="collDesc" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Description (Optional)
                  </label>
                  <textarea
                    id="collDesc"
                    placeholder="Provide details about this question pool..."
                    className="input"
                    style={{ width: '100%', minHeight: 80 }}
                    value={newCollDesc}
                    onChange={(e) => setNewCollDesc(e.target.value)}
                  />
                </div>

                <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', marginTop: 10 }}>
                  <button type="button" className="btn btn-secondary btn-pill" onClick={() => setIsCreateCollectionOpen(false)}>Cancel</button>
                  <button type="submit" className="btn btn-dark btn-pill">Create Pool</button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useAuthStore } from '@/store/auth.store';
import toast from 'react-hot-toast';
import { Eye, EyeOff } from 'lucide-react';

export default function RegisterPage() {
  const router = useRouter();
  const { signup, ssoLogin } = useAuthStore();
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [role, setRole] = useState<'STUDENT' | 'TEACHER'>('TEACHER');
  const [organizationId, setOrganizationId] = useState('');
  const [organizations, setOrganizations] = useState<{ id: string; name: string }[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showVerification, setShowVerification] = useState(false);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    
    // Fetch available organizations
    const fetchOrganizations = async () => {
      try {
        const { api } = await import('@/lib/api');
        const res = await api.get('/auth/public-organizations');
        if (res.data?.success) {
          setOrganizations(res.data.data);
          if (res.data.data.length > 0) {
            setOrganizationId(res.data.data[0].id);
          }
        }
      } catch (err) {
        console.error('Failed to load organizations', err);
      }
    };
    fetchOrganizations();

    const handleMessage = async (event: MessageEvent) => {
      if (event.data && event.data.type === 'SSO_SUCCESS') {
        setIsSubmitting(true);
        const result = await ssoLogin({
          email: event.data.email || 'faculty@vidyaai.com',
          firstName: event.data.firstName || 'Faculty',
          lastName: event.data.lastName || 'Member',
          provider: event.data.provider || 'SSO',
          token: event.data.token
        });
        setIsSubmitting(false);

        if (result.success) {
          toast.success(`Successfully registered and logged in with ${event.data.provider || 'SSO'}!`);
          const user = useAuthStore.getState().user;
          const isOnboarded = user?.hasCompletedOnboarding === true || (user?.organizationId && user?.departmentId);
          const rolePath = user?.role ? user.role.toLowerCase().replace('_', '-') : 'student';
          router.replace(isOnboarded ? `/dashboard/${rolePath}` : '/onboarding');
        } else {
          toast.error(result.error || 'SSO registration failed.');
        }
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [ssoLogin, router]);

  const handleSSO = (provider: 'google' | 'x') => {
    const googleClientId = process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID;
    const xClientId = process.env.NEXT_PUBLIC_X_CLIENT_ID;
    
    let isMock = false;
    if (provider === 'google') {
      isMock = !googleClientId || 
               googleClientId.includes('placeholder') || 
               !googleClientId.trim().endsWith('.apps.googleusercontent.com');
    } else {
      isMock = !xClientId || 
               xClientId.includes('placeholder');
    }

    if (!isMock) {
      const redirectUri = `${window.location.origin}/auth/callback?provider=${provider}`;
      let authUrl = '';
      if (provider === 'google') {
        const scope = encodeURIComponent('openid profile email');
        authUrl = `https://accounts.google.com/o/oauth2/v2/auth?client_id=${googleClientId?.trim()}&redirect_uri=${encodeURIComponent(redirectUri)}&response_type=token&scope=${scope}`;
      } else {
        const state = 'state_123';
        const codeChallenge = 'challenge';
        authUrl = `https://twitter.com/i/oauth2/authorize?response_type=code&client_id=${xClientId?.trim()}&redirect_uri=${encodeURIComponent(redirectUri)}&scope=users.read%20tweet.read&state=${state}&code_challenge=${codeChallenge}&code_challenge_method=plain`;
      }
      window.location.href = authUrl;
      return;
    }

    if (provider === 'google' && googleClientId && !googleClientId.trim().endsWith('.apps.googleusercontent.com')) {
      toast('Using simulated SSO login. The NEXT_PUBLIC_GOOGLE_CLIENT_ID in .env appears to be an API Key or invalid (must end with .apps.googleusercontent.com).', {
        icon: 'ℹ️',
        duration: 6000
      });
    } else {
      toast(`Using simulated SSO login. Set NEXT_PUBLIC_${provider.toUpperCase()}_CLIENT_ID in .env for real accounts.`, {
        icon: 'ℹ️',
        duration: 5000
      });
    }

    const width = 500;
    const height = 600;
    const left = window.screen.width / 2 - width / 2;
    const top = window.screen.height / 2 - height / 2;

    const popup = window.open(
      '',
      `sso_login_${provider}`,
      `width=${width},height=${height},top=${top},left=${left},status=no,menubar=no,toolbar=no`
    );

    if (!popup) {
      toast.error('Popup blocked! Please allow popups for this site.');
      return;
    }

    const providerName = provider === 'google' ? 'Google' : 'X';
    const providerColor = provider === 'google' ? '#4285F4' : '#000000';
    const providerLogo = provider === 'google' 
      ? `<svg viewBox="0 0 24 24" width="24" height="24" style="margin-right:8px;"><path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/><path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/><path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.06H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.94l2.85-2.22.81-.63z" fill="#FBBC05"/><path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.06l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/></svg>`
      : `<svg viewBox="0 0 24 24" width="24" height="24" fill="white" style="margin-right:8px;"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>`;

    popup.document.write(`
      <html>
        <head>
          <title>Sign in with ${providerName}</title>
          <style>
            body {
              font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
              background-color: #f3f4f6;
              margin: 0;
              display: flex;
              align-items: center;
              justify-content: center;
              height: 100vh;
              overflow: hidden;
            }
            .card {
              background: white;
              padding: 40px;
              border-radius: 16px;
              box-shadow: 0 10px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
              width: 380px;
              text-align: center;
            }
            .logo-container {
              display: flex;
              justify-content: center;
              align-items: center;
              margin-bottom: 24px;
            }
            h1 {
              font-size: 20px;
              font-weight: 600;
              color: #111827;
              margin: 0 0 8px 0;
            }
            p {
              font-size: 14px;
              color: #4b5563;
              margin: 0 0 24px 0;
              line-height: 1.5;
            }
            .profile-card {
              display: flex;
              align-items: center;
              background: #f9fafb;
              border: 1px solid #e5e7eb;
              border-radius: 12px;
              padding: 12px 16px;
              margin-bottom: 12px;
              text-align: left;
              cursor: pointer;
              transition: background-color 0.2s, border-color 0.2s;
            }
            .profile-card:hover {
              background: #f3f4f6;
              border-color: #d1d5db;
            }
            .avatar {
              width: 40px;
              height: 40px;
              border-radius: 50%;
              margin-right: 14px;
              display: flex;
              align-items: center;
              justify-content: center;
              font-size: 16px;
              font-weight: bold;
            }
            .profile-info {
              flex: 1;
            }
            .name {
              font-size: 14px;
              font-weight: 600;
              color: #111827;
            }
            .email {
              font-size: 12px;
              color: #6b7280;
            }
            .btn {
              width: 100%;
              padding: 12px;
              border-radius: 8px;
              border: none;
              font-size: 14px;
              font-weight: 600;
              cursor: pointer;
              transition: all 0.2s;
              display: flex;
              align-items: center;
              justify-content: center;
            }
            .btn-primary {
              background: ${providerColor};
              color: white;
              margin-bottom: 12px;
            }
            .btn-primary:hover {
              opacity: 0.9;
            }
            .btn-secondary {
              background: transparent;
              color: #4b5563;
              border: 1px solid #d1d5db;
            }
            .btn-secondary:hover {
              background: #f9fafb;
            }
            .loader {
              border: 3px solid #f3f3f3;
              border-top: 3px solid ${providerColor};
              border-radius: 50%;
              width: 24px;
              height: 24px;
              animation: spin 1s linear infinite;
              margin: 0 auto 16px auto;
              display: none;
            }
            @keyframes spin {
              0% { transform: rotate(0deg); }
              100% { transform: rotate(360deg); }
            }
          </style>
        </head>
        <body>
          <div class="card" id="card">
            <div class="logo-container">
              ${providerLogo}
              <span style="font-weight:700;font-size:18px;color:#111;">shiksha ai</span>
            </div>
            <h1 id="title">Sign in with ${providerName}</h1>
            <p id="desc">Choose an account to continue to <strong>shiksha ai</strong></p>
            
            <div id="loader" class="loader"></div>
            
            <div id="content">
              <!-- Account List -->
              <div id="account-list">
                <div class="profile-card" onclick="selectAccount('faculty@vidyaai.com', 'Faculty Member')">
                  <div class="avatar" style="background:#E0F2FE;color:#0369A1;">F</div>
                  <div class="profile-info">
                    <div class="name">Faculty Member</div>
                    <div class="email">faculty@vidyaai.com</div>
                  </div>
                </div>

                <div class="profile-card" onclick="selectAccount('student@vidyaai.com', 'Student Member')">
                  <div class="avatar" style="background:#DCFCE7;color:#15803D;">S</div>
                  <div class="profile-info">
                    <div class="name">Student Member</div>
                    <div class="email">student@vidyaai.com</div>
                  </div>
                </div>

                <div class="profile-card" onclick="selectAccount('admin@vidyaai.com', 'Org Administrator')">
                  <div class="avatar" style="background:#FEE2E2;color:#B91C1C;">A</div>
                  <div class="profile-info">
                    <div class="name">Org Administrator</div>
                    <div class="email">admin@vidyaai.com</div>
                  </div>
                </div>
                
                <button class="btn btn-secondary" style="margin-bottom:12px;" onclick="showCustomInput()">Use another account</button>
              </div>

              <!-- Custom Input Form (Hidden initially) -->
              <div id="custom-input-form" style="display:none; text-align:left;">
                <label style="font-size:13px; font-weight:600; color:#374151; display:block; margin-bottom:6px;">Email address</label>
                <input type="email" id="custom-email" placeholder="name@example.com" style="width:100%; padding:10px; border:1px solid #d1d5db; border-radius:6px; font-size:14px; margin-bottom:16px; box-sizing:border-box; outline:none;" />
                
                <div style="display:grid; grid-template-columns:1fr 1fr; gap:12px;">
                  <button class="btn btn-primary" onclick="submitCustomAccount()">Continue</button>
                  <button class="btn btn-secondary" onclick="showAccountList()">Back</button>
                </div>
              </div>

              <div style="margin-top:16px;">
                <button class="btn btn-secondary" onclick="window.close()">Cancel</button>
              </div>
            </div>
          </div>

          <script>
            let selectedEmail = '';
            let selectedName = '';

            function selectAccount(email, name) {
              selectedEmail = email;
              selectedName = name;
              proceed();
            }

            function showCustomInput() {
              document.getElementById('account-list').style.display = 'none';
              document.getElementById('custom-input-form').style.display = 'block';
              document.getElementById('title').innerText = 'Use another account';
              document.getElementById('desc').innerText = 'Enter your email to sign in using ${providerName}';
            }

            function showAccountList() {
              document.getElementById('account-list').style.display = 'block';
              document.getElementById('custom-input-form').style.display = 'none';
              document.getElementById('title').innerText = 'Sign in with ${providerName}';
              document.getElementById('desc').innerText = 'Choose an account to continue to shiksha ai';
            }

            function submitCustomAccount() {
              const emailVal = document.getElementById('custom-email').value.trim();
              if (!emailVal || !emailVal.includes('@')) {
                alert('Please enter a valid email address.');
                return;
              }
              selectedEmail = emailVal;
              selectedName = emailVal.split('@')[0];
              proceed();
            }

            function proceed() {
              document.getElementById('content').style.display = 'none';
              document.getElementById('title').innerText = 'Authorizing...';
              document.getElementById('desc').innerText = 'Connecting securely to shiksha ai.';
              document.getElementById('loader').style.display = 'block';
              
              setTimeout(() => {
                window.opener.postMessage({ 
                  type: 'SSO_SUCCESS', 
                  email: selectedEmail, 
                  firstName: selectedName, 
                  lastName: 'User', 
                  provider: '${providerName}' 
                }, '*');
                window.close();
              }, 1500);
            }
          </script>
        </body>
      </html>
    `);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!firstName || !lastName || !email || !password || !organizationId) {
      toast.error('All fields are required.');
      return;
    }

    if (password.length < 6) {
      toast.error('Password must be at least 6 characters long.');
      return;
    }

    setIsSubmitting(true);
    const signupResult = await signup({
      email,
      password,
      firstName,
      lastName,
      role,
      organizationId,
    });

    setIsSubmitting(false);

    if (signupResult.success) {
      toast.success('Account registered successfully!');
      const user = useAuthStore.getState().user;
      const isOnboarded = user?.hasCompletedOnboarding === true || (user?.organizationId && user?.departmentId);
      const rolePath = user?.role ? user.role.toLowerCase().replace('_', '-') : 'student';
      router.replace(isOnboarded ? `/dashboard/${rolePath}` : '/onboarding');
    } else {
      toast.error(signupResult.error || 'Registration failed. Email might already be registered.');
    }
  };

  // Falling petals generation helper
  const renderPetals = () => {
    if (!mounted) return null;
    return Array.from({ length: 20 }).map((_, i) => {
      const left = Math.random() * 100;
      const delay = Math.random() * 10;
      const duration = 6 + Math.random() * 6;
      const size = 6 + Math.random() * 8;
      
      return (
        <span 
          key={i} 
          className="petal"
          style={{
            left: `${left}%`,
            animationDelay: `${delay}s`,
            animationDuration: `${duration}s`,
            width: `${size}px`,
            height: `${size * 0.7}px`
          }}
        />
      );
    });
  };

  const cherryBlossomPanel = (
    <div className="art-panel">
      {renderPetals()}
