                  value={firstName}
                  onChange={(e) => setFirstName(e.target.value)}
                  disabled={isSubmitting}
                  required
                />
                <input
                  type="text"
                  className="input-box"
                  placeholder="Last name"
                  value={lastName}
                  onChange={(e) => setLastName(e.target.value)}
                  disabled={isSubmitting}
                  required
                />
              </div>

              <input
                type="email"
                className="input-box"
                placeholder="Email address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                disabled={isSubmitting}
                required
              />

              <div style={{ position: 'relative', marginBottom: '12px' }}>
                <input
                  type={showPassword ? 'text' : 'password'}
                  className="input-box"
                  placeholder="Password"
                  style={{ marginBottom: 0, paddingRight: '40px' }}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  disabled={isSubmitting}
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{
                    position: 'absolute',
                    right: '12px',
                    top: '50%',
                    transform: 'translateY(-50%)',
                    background: 'none',
                    border: 'none',
                    color: '#9CA3AF',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    padding: 0
                  }}
                  tabIndex={-1}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>

              <div className="inline-inputs">
                <select 
                  className="input-box" 
                  value={role} 
                  onChange={(e) => setRole(e.target.value as 'STUDENT' | 'TEACHER')}
                  disabled={isSubmitting}
                >
                  <option value="STUDENT">Student</option>
                  <option value="TEACHER">Faculty</option>
                </select>

                <select 
                  className="input-box" 
                  value={organizationId} 
                  onChange={(e) => setOrganizationId(e.target.value)}
                  disabled={organizations.length === 0 || isSubmitting}
                  required
                >
                  {organizations.length === 0 ? (
                    <option value="">Loading organizations...</option>
                  ) : (
                    organizations.map((org) => (
                      <option key={org.id} value={org.id}>
                        {org.name}
                      </option>
                    ))
                  )}
                </select>
              </div>

              <button type="submit" className="btn-submit-arrow" disabled={isSubmitting || !organizationId}>
                {isSubmitting ? 'Signing up...' : 'Sign up →'}
              </button>
            </form>
            
            <div className="login-link-container" style={{ marginTop: '20px', fontSize: '13px', textAlign: 'center' }}>
              Already have an account? <Link href="/login" style={{ fontWeight: '700', textDecoration: 'underline' }}>Log in</Link>
            </div>
          </div>

          <div className="footer-row-meta">
            <span>© 2026 shiksha ai</span>
            <div>
              <a href="#">Privacy</a>
              <a href="#">Terms</a>
            </div>
          </div>
        </div>

        {/* Right Cherry Blossom Column */}
        {cherryBlossomPanel}
      </div>
    </div>
  );
}

