'use client';

import { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { Building2, Plus, Edit3, Trash2, Power, Search, Mail, Phone, MapPin } from 'lucide-react';
import Link from 'next/link';
import toast from 'react-hot-toast';
import { PageHeader } from '@/design-system/PageHeader';
import { DataTable } from '@/design-system/DataTable';
import { Badge } from '@/design-system/Badge';
import { Dialog } from '@/design-system/Dialog';
import { Button } from '@/design-system/Button';
import { Input } from '@/design-system/Input';
import { Select } from '@/design-system/Select';
import { EmptyState } from '@/design-system/EmptyState';
import { LoadingState } from '@/design-system/LoadingState';

interface Organization {
  id: string;
  name: string;
  code: string;
  email?: string;
  phone?: string;
  address?: string;
  status: string;
  subscriptionPlan: string;
  createdAt: string;
  _count?: { users: number };
}

export default function SuperAdminOrganizations() {
  const [list, setList] = useState<Organization[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');

  const [showModal, setShowModal] = useState(false);
  const [modalType, setModalType] = useState<'create' | 'edit'>('create');
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const [name, setName] = useState('');
  const [code, setCode] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');

  const load = async () => {
    try {
      setLoading(true);
      const res = await api.get('/super-admin/organizations');
      if (res.data?.success) setList(res.data.data);
    } catch { toast.error('Failed to load organizations'); }
    finally { setLoading(false); }
  };

  useEffect(() => { load(); }, []);

  const openCreate = () => {
    setModalType('create'); setSelectedId(null);
    setName(''); setCode(''); setEmail(''); setPhone(''); setAddress('');
    setShowModal(true);
  };

  const openEdit = (org: Organization) => {
    setModalType('edit'); setSelectedId(org.id);
    setName(org.name); setCode(org.code);
    setEmail(org.email || ''); setPhone(org.phone || ''); setAddress(org.address || '');
    setShowModal(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !code) { toast.error('Name and Code are required.'); return; }
    const payload = { name, code, email, phone, address };
    try {
      if (modalType === 'create') {
        const res = await api.post('/super-admin/organizations', payload);
        if (res.data?.success) { toast.success('Organization created!'); setShowModal(false); load(); }
      } else {
        const res = await api.put(`/super-admin/organizations/${selectedId}`, payload);
        if (res.data?.success) { toast.success('Organization updated!'); setShowModal(false); load(); }
      }
    } catch (err) { toast.error(err instanceof Error ? err.message : 'Operation failed'); }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Permanently delete this organization? This cannot be undone.')) return;
    try {
      const res = await api.delete(`/super-admin/organizations/${id}`);
      if (res.data?.success) { toast.success('Organization deleted.'); load(); }
    } catch (err) { toast.error(err instanceof Error ? err.message : 'Delete failed'); }
  };

  const handleToggleSuspend = async (org: Organization) => {
    const isSuspended = org.status === 'SUSPENDED';
    if (!confirm(`Are you sure you want to ${isSuspended ? 'activate' : 'suspend'} ${org.name}?`)) return;
    try {
      const res = await api.post(`/super-admin/organizations/${org.id}/suspend`);
      if (res.data?.success) { toast.success(`Organization ${isSuspended ? 'activated' : 'suspended'}.`); load(); }
    } catch (err) { toast.error(err instanceof Error ? err.message : 'Failed to update status'); }
  };

  const filtered = list.filter(org => {
    const matchSearch = org.name.toLowerCase().includes(search.toLowerCase()) || org.code.toLowerCase().includes(search.toLowerCase());
    const matchStatus = !statusFilter || org.status === statusFilter;
    return matchSearch && matchStatus;
  });

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16, flexWrap: 'wrap' }}>
        <PageHeader
          title="Organizations"
          subtitle="Manage all tenant organizations on the platform."
        />
        <Button variant="primary" size="sm" icon={<Plus size={16} />} onClick={openCreate}>
          Create Organization
        </Button>
      </div>

      <div style={{ display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap' }}>
        <Input
          icon={<Search size={16} />}
          placeholder="Search by name or code..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={{ maxWidth: 320 }}
        />
        <Select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          options={[
            { value: '', label: 'All Status' },
            { value: 'ACTIVE', label: 'Active' },
            { value: 'SUSPENDED', label: 'Suspended' },
            { value: 'INACTIVE', label: 'Inactive' },
          ]}
        />
      </div>

      {loading ? (
        <LoadingState lines={5} />
      ) : filtered.length === 0 ? (
        <EmptyState
          icon={<Building2 size={32} />}
          title="No organizations found"
          description="Try adjusting your search or create a new organization."
          action={search || statusFilter ? undefined : openCreate}
          actionLabel={search || statusFilter ? undefined : 'Create Organization'}
        />
      ) : (
        <DataTable
          columns={[
            { key: 'name', header: 'Name', render: (_: any, row: Organization) => (
              <Link href={`/super-admin/organizations/${row.id}`} style={{ fontWeight: 700, color: 'var(--text-primary)', textDecoration: 'none', display: 'flex', alignItems: 'center', gap: 6 }}>
                <Building2 size={14} color="var(--brand)" />
                {row.name}
              </Link>
            )},
            { key: 'code', header: 'Code' },
            { key: 'status', header: 'Status', render: (value: string) => (
              <Badge variant={value === 'ACTIVE' ? 'success' : value === 'SUSPENDED' ? 'error' : 'draft'}>{value}</Badge>
            )},
            { key: 'subscriptionPlan', header: 'Plan' },
            { key: '_count', header: 'Users', align: 'center', render: (_: any, row: Organization) => row._count?.users || 0 },
            { key: 'createdAt', header: 'Created', render: (value: string) => new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) },
            { key: 'id', header: 'Actions', align: 'right', render: (_: any, row: Organization) => (
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: 4 }}>
                <Button variant="ghost" size="sm" icon={<Edit3 size={14} />} onClick={() => openEdit(row)} />
                <Button variant="ghost" size="sm" icon={<Power size={14} />} onClick={() => handleToggleSuspend(row)} />
                <Button variant="ghost" size="sm" icon={<Trash2 size={14} />} onClick={() => handleDelete(row.id)} />
              </div>
            )},
          ]}
          data={filtered}
        />
      )}

      <Dialog
        open={showModal}
        onClose={() => setShowModal(false)}
        title={modalType === 'create' ? 'Create Organization' : 'Edit Organization'}
        size="sm"
      >
        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <Input label="Name *" required value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Acme University" />
            <Input label="Code *" required value={code} onChange={(e) => setCode(e.target.value)} placeholder="e.g. ACME" />
          </div>
          <Input label="Email" icon={<Mail size={14} />} type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="admin@acme.edu" />
          <Input label="Phone" icon={<Phone size={14} />} value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="+1-555-1234" />
          <Input label="Address" icon={<MapPin size={14} />} value={address} onChange={(e) => setAddress(e.target.value)} placeholder="123 Main St, City" />
          <div style={{ display: 'flex', gap: 8 }}>
            <Button variant="secondary" onClick={() => setShowModal(false)} style={{ flex: 1 }} type="button">Cancel</Button>
            <Button variant="primary" style={{ flex: 1 }} type="submit">
              {modalType === 'create' ? 'Create Organization' : 'Update Organization'}
            </Button>
          </div>
        </form>
      </Dialog>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { useAuthStore } from '@/store/auth.store';
import {
  Building2,
  Users,
  FileText,
  ChevronRight,
  ShieldCheck,
  BarChart3,
  ListChecks,
  DollarSign,
} from 'lucide-react';
import Link from 'next/link';
import { PageHeader } from '@/design-system/PageHeader';
import { MetricCard } from '@/design-system/MetricCard';
import { ActionCard } from '@/design-system/ActionCard';
import { Card } from '@/design-system/Card';
import { DataTable } from '@/design-system/DataTable';
import { Badge } from '@/design-system/Badge';
import { LoadingState } from '@/design-system/LoadingState';
import { ErrorState } from '@/design-system/ErrorState';

interface SuperAdminStats {
  totalOrganizations: number;
  totalUsers: number;
  activeUsers: number;
  totalAssessments: number;
  totalPapers: number;
  revenue: { total: number; monthly: number };
  recentOrganizations: Array<{
    id: string;
    name: string;
    code: string;
    status: string;
    subscriptionPlan: string;
    createdAt: string;
    _count?: { users: number };
  }>;
  health: {
    api: boolean;
    database: boolean;
    ai: boolean;
    storage: boolean;
  };
}

export default function SuperAdminDashboard() {
  const { user } = useAuthStore();
  const [data, setData] = useState<SuperAdminStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      try {
        const res = await api.get('/super-admin/dashboard');
        if (res.data?.success) {
          setData(res.data.data);
        } else {
          setError('Failed to load dashboard');
        }
      } catch {
        setError('Failed to load dashboard');
      } finally {
        setLoading(false);
      }
    }
    load();
  }, []);

  if (loading) return <LoadingState lines={8} />;
  if (error) return <ErrorState message={error} onRetry={() => { setLoading(true); setError(null); }} />;

  const stats = data || {
    totalOrganizations: 0, totalUsers: 0, activeUsers: 0, totalAssessments: 0, totalPapers: 0,
    revenue: { total: 0, monthly: 0 },
    recentOrganizations: [],
    health: { api: true, database: true, ai: true, storage: true }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16, flexWrap: 'wrap' }}>
        <PageHeader
          title="Super Admin Dashboard"
          subtitle={`Welcome back, ${user?.firstName || 'Super Admin'}. Platform overview at a glance.`}
        />
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, background: '#D1FAE5', border: '1px solid #A7F3D0', color: '#065F46', padding: '8px 14px', borderRadius: 'var(--radius-lg)', fontSize: 'var(--text-xs)', fontWeight: 700, flexShrink: 0 }}>
          <ShieldCheck size={16} />
          <span>All Systems Operational</span>
        </div>
      </div>

      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(4, minmax(0, 1fr))',
        gap: 12,
      }}>
        <MetricCard
          icon={<Building2 size={18} />}
          label="Total Organizations"
          value={stats.totalOrganizations}
        />
        <MetricCard
          icon={<Users size={18} />}
          label="Total Users"
          value={stats.totalUsers}
          description={`Active: ${stats.activeUsers}`}
        />
        <MetricCard
          icon={<FileText size={18} />}
          label="Total Assessments"
          value={stats.totalAssessments}
          description={`Papers: ${stats.totalPapers}`}
        />
        <MetricCard
          icon={<DollarSign size={18} />}
          label="Revenue"
          value={`$${stats.revenue.total.toFixed(2)}`}
          description={`Monthly: $${stats.revenue.monthly.toFixed(2)}`}
        />
      </div>

      <div style={{
        display: 'grid',
        gridTemplateColumns: '2fr 1fr',
        gap: 16,
      }}>
        <Card padding="clamp(16px, 2vw, 20px)">
          <h3 style={{ fontSize: 'var(--text-sm)', fontWeight: 700, color: 'var(--text-primary)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 16 }}>
            Revenue Trend
          </h3>
          <div style={{ display: 'flex', alignItems: 'flex-end', gap: 2, height: 160 }}>
            {[20, 40, 30, 70, 50, 80, 90, 65, 85, 95, 75, 100].map((h, i) => (
              <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
                <div style={{ width: '100%', background: 'var(--brand)', borderRadius: '4px 4px 0 0', height: `${h}px`, opacity: 0.5 + (h / 200) }} />
                <span style={{ fontSize: '8px', color: 'var(--text-muted)', fontWeight: 700 }}>
                  {['J','F','M','A','M','J','J','A','S','O','N','D'][i]}
                </span>
              </div>
            ))}
          </div>
        </Card>

        <Card padding="clamp(16px, 2vw, 20px)">
          <h3 style={{ fontSize: 'var(--text-sm)', fontWeight: 700, color: 'var(--text-primary)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 16 }}>
            Quick Actions
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            <ActionCard
              icon={<Building2 size={16} />}
              label="Create Organization"
              href="/super-admin/organizations"
              variant="primary"
            />
            <ActionCard
              icon={<ListChecks size={16} />}
              label="View Audit Logs"
              href="/super-admin/audit"
            />
            <ActionCard
              icon={<BarChart3 size={16} />}
              label="View Analytics"
              href="/super-admin/analytics"
              variant="primary"
            />
          </div>
        </Card>
      </div>

      <div style={{
        display: 'grid',
        gridTemplateColumns: '2fr 1fr',
        gap: 16,
      }}>
        <Card padding="clamp(16px, 2vw, 20px)">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
            <h3 style={{ fontSize: 'var(--text-sm)', fontWeight: 700, color: 'var(--text-primary)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
              Recent Organizations
            </h3>
            <Link href="/super-admin/organizations" style={{ fontSize: 'var(--text-xs)', fontWeight: 600, color: 'var(--brand)', textDecoration: 'none', display: 'flex', alignItems: 'center', gap: 4 }}>
              View All <ChevronRight size={14} />
            </Link>
          </div>
          <DataTable
            columns={[
              { key: 'name', header: 'Name' },
              { key: 'code', header: 'Code' },
              {
                key: 'status',
                header: 'Status',
                render: (value: string) => (
                  <Badge variant={value === 'ACTIVE' ? 'success' : 'error'}>{value}</Badge>
                ),
              },
              { key: 'subscriptionPlan', header: 'Plan' },
              {
                key: '_count',
                header: 'Users',
                align: 'right',
                render: (_: any, row: any) => row._count?.users || 0,
              },
            ]}
            data={stats.recentOrganizations}
            emptyMessage="No organizations yet"
          />
        </Card>

        <Card padding="clamp(16px, 2vw, 20px)">
          <h3 style={{ fontSize: 'var(--text-sm)', fontWeight: 700, color: 'var(--text-primary)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 16 }}>
            Platform Health
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {[
              { label: 'API Service', key: 'api' as const },
              { label: 'Database', key: 'database' as const },
              { label: 'AI Engine', key: 'ai' as const },
              { label: 'Storage', key: 'storage' as const },
            ].map(({ label, key }) => (
              <div key={key} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 12px', background: 'var(--bg-hover)', borderRadius: 'var(--radius-md)' }}>
                <span style={{ fontSize: 'var(--text-sm)', fontWeight: 600, color: 'var(--text-primary)' }}>{label}</span>
                <Badge variant={stats.health[key] ? 'success' : 'error'}>
                  {stats.health[key] ? 'Operational' : 'Down'}
                </Badge>
              </div>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { PageHeader } from '@/design-system/PageHeader';
import { DataTable } from '@/design-system/DataTable';
import { Badge } from '@/design-system/Badge';
import { Input } from '@/design-system/Input';
import { LoadingState } from '@/design-system/LoadingState';
import { ErrorState } from '@/design-system/ErrorState';
import { Search, Mail, Building2 } from 'lucide-react';
import toast from 'react-hot-toast';
import { formatDate } from '@/utils/format';

interface User {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  role: string;
  status: string;
  organization?: { name: string } | null;
  createdAt: string;
}

export default function SuperAdminUsersPage() {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');

  const loadUsers = async () => {
    try {
      setLoading(true);
      const res = await api.get('/super-admin/users');
      if (res.data?.success) {
        setUsers(res.data.data || []);
      } else {
        setError('Failed to load users');
      }
    } catch (err) {
      setError('Failed to load users');
      toast.error('Failed to load users');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadUsers();
  }, []);

  const filteredUsers = users.filter(u =>
    `${u.firstName} ${u.lastName}`.toLowerCase().includes(search.toLowerCase()) ||
    u.email.toLowerCase().includes(search.toLowerCase()) ||
    u.organization?.name.toLowerCase().includes(search.toLowerCase())
  );

  if (loading) return <LoadingState lines={6} />;
  if (error) return <ErrorState message={error} onRetry={loadUsers} />;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      <PageHeader
        title="User Directory"
        subtitle="View all users for the selected organization."
      />

      <Input
        icon={<Search size={16} />}
        placeholder="Search by name, email, or organization..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        style={{ maxWidth: 400 }}
      />

      <DataTable
        columns={[
          {
            key: 'name',
            header: 'Name',
            render: (_: any, row: User) => (
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontWeight: 600, color: 'var(--text-primary)' }}>
                {row.firstName} {row.lastName}
              </div>
            ),
          },
          {
            key: 'email',
            header: 'Email',
            render: (value: string) => (
              <span style={{ display: 'flex', alignItems: 'center', gap: 4, color: 'var(--text-secondary)' }}>
                <Mail size={12} /> {value}
              </span>
            ),
          },
          {
            key: 'organization',
            header: 'Organization',
            render: (_: any, row: User) => (
              <span style={{ display: 'flex', alignItems: 'center', gap: 4, color: 'var(--text-secondary)' }}>
                <Building2 size={12} /> {row.organization?.name || 'N/A'}
              </span>
            ),
          },
          {
            key: 'role',
            header: 'Role',
            render: (value: string) => (
              <Badge variant="info">{value}</Badge>
            ),
          },
          {
            key: 'status',
            header: 'Status',
            align: 'center',
            render: (value: string) => (
              <Badge variant={value === 'ACTIVE' ? 'success' : value === 'SUSPENDED' ? 'error' : 'warning'}>
                {value || 'ACTIVE'}
              </Badge>
            ),
          },
          {
            key: 'createdAt',
            header: 'Created',
            render: (value: string) => formatDate(value),
          },
        ]}
        data={filteredUsers}
        emptyMessage={search ? 'No users match your search' : 'No users found'}
      />
    </div>
  );
}

