'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Plus, Loader2, FileText, Trash2, Calendar, Sparkles, X 
} from 'lucide-react';
import toast from 'react-hot-toast';
import { apiClient } from '@/services/api.client';
import { formatDate } from '@/utils/format';

interface Worksheet {
  id: string;
  title: string;
  subject: string;
  topic: string;
  difficulty: 'EASY' | 'MEDIUM' | 'HARD';
  content: string;
  answerKey: string;
  createdAt: string;
}

export default function WorksheetsPage() {
  const [sheets, setSheets] = useState<Worksheet[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedSheet, setSelectedSheet] = useState<Worksheet | null>(null);
  const [sheetTab, setSheetTab] = useState<'worksheet' | 'answers'>('worksheet');

  // Wizard state
  const [isOpen, setIsOpen] = useState(false);
  const [title, setTitle] = useState('');
  const [subject, setSubject] = useState('Computer Science');
  const [topic, setTopic] = useState('');
  const [difficulty, setDifficulty] = useState<'EASY' | 'MEDIUM' | 'HARD'>('MEDIUM');
  const [generating, setGenerating] = useState(false);

  const fetchSheets = async () => {
    setLoading(true);
    try {
      const res = await apiClient.get<{ success: boolean; data: Worksheet[] }>('/worksheets');
      setSheets(res.data.data);
    } catch {
      toast.error('Failed to load worksheets');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSheets();
  }, []);

  const handleGenerateSheet = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !topic.trim()) {
      toast.error('All fields are required');
      return;
    }
    setGenerating(true);
    try {
      const res = await apiClient.post<{ success: boolean; data: Worksheet }>('/worksheets', {
        title,
        subject,
        topic,
        difficulty
      });
      toast.success('Worksheet generated successfully!');
      setSheets(prev => [res.data.data, ...prev]);
      setIsOpen(false);
      setTitle('');
      setTopic('');
    } catch (err) {
      toast.error('Failed to generate worksheet');
    } finally {
      setGenerating(false);
    }
  };

  const handleDeleteSheet = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!window.confirm('Delete this worksheet?')) return;
    try {
      await apiClient.delete(`/worksheets/${id}`);
      toast.success('Worksheet deleted');
      setSheets(prev => prev.filter(s => s.id !== id));
      if (selectedSheet?.id === id) setSelectedSheet(null);
    } catch {
      toast.error('Failed to delete worksheet');
    }
  };

  return (
    <div style={{ padding: 'var(--page-pad)', maxWidth: 'var(--page-max-w)', margin: '0 auto', width: '100%' }}>
      {/* Header */}
      <div className="desktop-page-header">
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%', flexWrap: 'wrap', gap: 12 }}>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <FileText size={24} color="var(--brand)" />
              <h1 className="page-title">Worksheet Generator</h1>
            </div>
            <p className="page-subtitle">Instantly generate student revision sheets and matching step-by-step teacher keys.</p>
          </div>
          <button className="btn btn-dark btn-pill" onClick={() => setIsOpen(true)} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <Plus size={16} />
            Generate Worksheet
          </button>
        </div>
      </div>

      {loading ? (
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: 20, color: 'var(--text-muted)' }}>
          <Loader2 size={18} className="animate-spin" /> Loading sheets...
        </div>
      ) : sheets.length === 0 ? (
        <div className="empty-state">
          <FileText size={40} color="#9CA3AF" />
          <h2 className="empty-title">No Worksheets Yet</h2>
          <p className="empty-desc">Create custom practice sheets with matching answer guides for homework or exam prep.</p>
          <div className="empty-state-actions">
            <button className="btn btn-dark btn-pill" onClick={() => setIsOpen(true)}>Generate Worksheet</button>
          </div>
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 16 }}>
          {sheets.map((sheet) => (
            <div 
              key={sheet.id} 
              className="card" 
              style={{ cursor: 'pointer', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', gap: 12 }}
              onClick={() => { setSelectedSheet(sheet); setSheetTab('worksheet'); }}
            >
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 8 }}>
                  <span className={`badge ${sheet.difficulty === 'EASY' ? 'badge-completed' : sheet.difficulty === 'HARD' ? 'badge-failed' : 'badge-pending'}`}>
                    {sheet.difficulty}
                  </span>
                  <button
                    onClick={(e) => handleDeleteSheet(sheet.id, e)}
                    style={{ border: 'none', background: 'transparent', cursor: 'pointer', color: 'var(--text-muted)' }}
                    title="Delete Worksheet"
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
                <h3 style={{ fontSize: 15, fontWeight: 700, marginTop: 8, color: 'var(--text-primary)' }}>{sheet.title}</h3>
                <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 4 }}>
                  {sheet.subject} &middot; {sheet.topic}
                </div>
              </div>
              <div style={{ borderTop: '1px solid var(--border)', paddingTop: 10, display: 'flex', justifyContent: 'space-between', fontSize: 11, color: 'var(--text-muted)' }}>
                <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                  <Calendar size={12} /> {formatDate(sheet.createdAt)}
                </span>
                <span>View Sheet &rarr;</span>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* View Worksheet / Answer Key Modal */}
      <AnimatePresence>
        {selectedSheet && (
          <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setSelectedSheet(null)}
              style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(2px)' }} 
            />
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 16 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 16 }}
              className="card"
              style={{ width: '100%', maxWidth: 720, position: 'relative', zIndex: 101, padding: 24, maxHeight: '85vh', overflowY: 'auto' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
                <div>
                  <h3 style={{ fontSize: 18, fontWeight: 800, margin: 0 }}>{selectedSheet.title}</h3>
                  <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 4 }}>
                    {selectedSheet.subject} &middot; {selectedSheet.topic}
                  </div>
                </div>
                <button onClick={() => setSelectedSheet(null)} style={{ border: 'none', background: 'transparent', cursor: 'pointer', color: 'var(--text-muted)' }}>
                  <X size={18} />
                </button>
              </div>

              {/* Toggle Worksheet/AnswerKey */}
              <div style={{ display: 'flex', borderBottom: '1px solid var(--border)', gap: 16, fontSize: 13, marginBottom: 16 }}>
                <button
                  onClick={() => setSheetTab('worksheet')}
                  style={{
                    border: 'none',
                    background: 'transparent',
                    padding: '8px 4px',
                    fontWeight: 600,
                    color: sheetTab === 'worksheet' ? 'var(--brand)' : 'var(--text-secondary)',
                    borderBottom: sheetTab === 'worksheet' ? '2px solid var(--brand)' : '2px solid transparent',
                    cursor: 'pointer'
                  }}
                >
                  Student Worksheet
                </button>
                <button
                  onClick={() => setSheetTab('answers')}
                  style={{
                    border: 'none',
                    background: 'transparent',
                    padding: '8px 4px',
                    fontWeight: 600,
                    color: sheetTab === 'answers' ? 'var(--brand)' : 'var(--text-secondary)',
                    borderBottom: sheetTab === 'answers' ? '2px solid var(--brand)' : '2px solid transparent',
                    cursor: 'pointer'
                  }}
                >
                  Teacher Answer Key
                </button>
              </div>

              <div 
                style={{ fontSize: 14, lineHeight: 1.6, color: '#334155', whiteSpace: 'pre-wrap', fontFamily: 'monospace', background: 'var(--bg-secondary)', padding: 16, borderRadius: 8 }}
              >
                {sheetTab === 'worksheet' ? selectedSheet.content : selectedSheet.answerKey}
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Generate Wizard Modal */}
      <AnimatePresence>
        {isOpen && (
          <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsOpen(false)}
              style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(2px)' }} 
            />
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 16 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 16 }}
              className="card"
              style={{ width: '100%', maxWidth: 460, position: 'relative', zIndex: 101, padding: 24 }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
                <h3 style={{ fontSize: 18, fontWeight: 800, display: 'flex', alignItems: 'center', gap: 8 }}>
                  <Sparkles size={20} color="var(--brand)" />
                  AI Worksheet Builder
                </h3>
                <button onClick={() => setIsOpen(false)} style={{ border: 'none', background: 'transparent', cursor: 'pointer', color: 'var(--text-muted)' }}>
                  <X size={18} />
                </button>
              </div>

              <form onSubmit={handleGenerateSheet} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                <div>
                  <label htmlFor="sheetTitle" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Worksheet Title
                  </label>
                  <input
                    id="sheetTitle"
                    type="text"
                    required
                    placeholder="e.g. Calculus Derivatives Homework"
                    className="input"
                    style={{ width: '100%' }}
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                  />
                </div>

                <div>
                  <label htmlFor="sheetSubject" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Subject
                  </label>
                  <select
                    id="sheetSubject"
                    className="input"
                    style={{ width: '100%', height: 38 }}
                    value={subject}
                    onChange={(e) => setSubject(e.target.value)}
                  >
                    <option value="Computer Science">Computer Science</option>
                    <option value="Mathematics">Mathematics</option>
                    <option value="Physics">Physics</option>
                    <option value="Chemistry">Chemistry</option>
                    <option value="Biology">Biology</option>
                  </select>
                </div>

                <div>
                  <label htmlFor="sheetTopic" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Topic Coverage details
                  </label>
                  <input
                    id="sheetTopic"
                    type="text"
                    required
                    placeholder="e.g. Chain rule, quotient rule, and product rule"
                    className="input"
                    style={{ width: '100%' }}
                    value={topic}
                    onChange={(e) => setTopic(e.target.value)}
                  />
                </div>

                <div>
                  <label htmlFor="sheetDiff" style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 6 }}>
                    Difficulty level
                  </label>
                  <select
                    id="sheetDiff"
                    className="input"
                    style={{ width: '100%', height: 38 }}
                    value={difficulty}
                    onChange={(e) => setDifficulty(e.target.value as any)}
                  >
                    <option value="EASY">Easy</option>
                    <option value="MEDIUM">Medium</option>
                    <option value="HARD">Hard</option>
                  </select>
                </div>

                <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', marginTop: 10 }}>
                  <button type="button" className="btn btn-secondary btn-pill" onClick={() => setIsOpen(false)}>Cancel</button>
                  <button type="submit" className="btn btn-dark btn-pill" disabled={generating} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                    {generating ? <Loader2 size={14} className="animate-spin" /> : <Sparkles size={14} />}
                    Generate Worksheet
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import { Menu, ShieldAlert, ArrowLeft, UserCircle, ChevronRight } from 'lucide-react';
import { useSidebarStore } from '@/store/sidebar.store';
import { useAuthStore } from '@/store/auth.store';
import { useAdminAuthStore } from '@/store/admin-auth.store';
import { usePathname, useRouter } from 'next/navigation';
import Link from 'next/link';

export function AdminTopbar() {
  const { toggle } = useSidebarStore();
  const { user } = useAuthStore();
  const { isImpersonating, exitImpersonation } = useAdminAuthStore();
  const pathname = usePathname();
  const router = useRouter();

  // Create human-readable breadcrumbs from the pathname
  const paths = pathname.split('/').filter(Boolean);
  const breadcrumbs = paths.map((path, index) => {
    const href = '/' + paths.slice(0, index + 1).join('/');
    const label = path.charAt(0).toUpperCase() + path.slice(1).replace('-', ' ');
    const isLast = index === paths.length - 1;
    return { href, label, isLast };
  });

  return (
    <header style={{
      position: 'sticky',
      top: 0,
      zIndex: 30,
      height: '60px',
      background: '#FFFFFF',
      borderBottom: '1px solid #E5E7EB',
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      flexShrink: 0,
    }}>
      {/* Impersonation Banner Alert */}
      {isImpersonating && (
        <div className="w-full bg-amber-500 text-white px-4 py-2 text-xs md:text-sm font-semibold flex items-center justify-between gap-2 shadow-sm animate-pulse">
          <div className="flex items-center gap-2">
            <ShieldAlert size={16} />
            <span>
              Impersonation Active: Viewing workspace as <strong>{user?.email}</strong> ({user?.role})
            </span>
          </div>
          <button
            onClick={() => exitImpersonation()}
            className="bg-white text-amber-700 hover:bg-amber-100 px-3 py-1 rounded-md font-bold transition-all text-xs flex items-center gap-1 shadow-sm"
          >
            <ArrowLeft size={12} />
            Exit Impersonation
          </button>
        </div>
      )}

      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 24px', height: '60px', flex: 1 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <button
            onClick={toggle}
            className="p-2 hover:bg-gray-100 rounded-lg lg:hidden transition-colors"
            aria-label="Toggle navigation menu"
          >
            <Menu size={20} />
          </button>

          {/* Breadcrumbs */}
          <nav style={{ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '12px', color: '#6B7280', fontWeight: 500 }}>
            <Link href="/admin" style={{ color: '#6B7280' }} className="hover:text-blue-600 transition-colors">
              Admin
            </Link>
            {breadcrumbs.slice(1).map((b) => (
              <div key={b.href} style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                <ChevronRight size={12} color="#9CA3AF" />
                {b.isLast ? (
                  <span style={{ color: '#111827', fontWeight: 600 }}>{b.label}</span>
                ) : (
                  <Link href={b.href} style={{ color: '#6B7280' }} className="hover:text-blue-600 transition-colors">
                    {b.label}
                  </Link>
                )}
              </div>
            ))}
          </nav>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ textAlign: 'right' }}>
            <div style={{ fontSize: '12px', fontWeight: 700, color: '#111827' }}>
              {user ? `${user.firstName} ${user.lastName}` : 'Administrator'}
            </div>
            <div style={{ fontSize: '10px', color: '#6B7280' }}>{user?.email}</div>
          </div>

          <div style={{ width: '32px', height: '32px', borderRadius: '50%', background: '#EFF6FF', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#2563EB' }}>
            <UserCircle size={22} />
          </div>
        </div>
      </div>
    </header>
  );
}

'use client';
import { useMemo } from 'react';
import { useGenerationStore } from '@/store/generation.store';
import { PIPELINE_STEPS } from '@/constants/pipelineSteps';
import type { GenerationStage } from '@/types/socket.types';
import { SuccessView } from './SuccessView';
import { ErrorView } from './ErrorView';

const EXTRA_STEPS: { stage: GenerationStage; label: string; description: string }[] = [
  { stage: 'provider_retry', label: 'Reconnecting AI', description: 'Retrying AI provider connection' },
  { stage: 'validation_retry', label: 'Re-validating', description: 'Retrying content validation' },
  { stage: 'recovering_batches', label: 'Recovering Sections', description: 'Rebuilding failed sections' },
  { stage: 'answer_key_generating', label: 'Preparing Answer Key', description: 'Generating model answers' },
];

const ALL_STAGES_INFO = [...PIPELINE_STEPS, ...EXTRA_STEPS];
const ALL_STAGES = ALL_STAGES_INFO.map(s => s.stage);

export interface GenerationScreenProps {
  assignmentTitle: string;
  assignmentSubject: string;
  assignmentId: string;
  duration: number;
  generatedQuestionCount: number | null;
  requestedQuestionCount: number | null;
  generatedMarks: number | null | undefined;
  requestedMarks: number | null | undefined;
  schoolName?: string;
  className?: string;
  isPartial: boolean;
  onRetry: () => void;
  isRetrying: boolean;
}

export function GenerationScreen({
  assignmentTitle, assignmentSubject, assignmentId, duration,
  generatedQuestionCount, requestedQuestionCount,
  generatedMarks, requestedMarks, schoolName, className, isPartial,
  onRetry, isRetrying,
}: GenerationScreenProps) {
  const { stage, status, progress, message, error } = useGenerationStore();

  const currentStageInfo = useMemo(() => {
    if (!stage || stage === 'failed') return ALL_STAGES_INFO[0];
    const info = ALL_STAGES_INFO.find(s => s.stage === stage);
    return info || ALL_STAGES_INFO[0];
  }, [stage]);

  const showSuccess = status === 'completed' || status === 'partial_success' || isPartial;
  const showError = status === 'failed' || stage === 'failed';
  const showProgress = !showSuccess && !showError;

  const progressValue = Math.round(showSuccess ? 100 : Math.min(99, progress));
  const progressText = message?.trim()
    ? message
    : `${currentStageInfo.description}. Please hold while we finalize this stage.`;
  const progressStrokeOffset = 289 - (289 * Math.max(0, Math.min(100, progressValue))) / 100;

  const resolvedSchoolName = schoolName && schoolName.trim() ? schoolName : 'Delhi Public School';
  const resolvedClassName =
    className &&
    className.trim() &&
    className.trim().toLowerCase() !== 'not specified' &&
    className.trim().toLowerCase() !== 'class not specified'
      ? className
      : 'Class 8';
  const resolvedSubjectName =
    assignmentSubject &&
    assignmentSubject.trim() &&
    assignmentSubject.trim().toLowerCase() !== 'not specified'
      ? assignmentSubject
      : 'Mathematics';
  const cleanedSchoolName =
    resolvedSchoolName.trim().toLowerCase() === 'school'
      ? 'Delhi Public School'
      : resolvedSchoolName;

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-gray-50 overflow-y-auto">
      <div className="absolute inset-0 pointer-events-none opacity-[0.03] mix-blend-multiply" style={{ backgroundImage: 'radial-gradient(circle at center, #000 1px, transparent 1px)', backgroundSize: '24px 24px' }}></div>

      <div className="flex-shrink-0 flex items-center justify-between px-6 sm:px-12 py-5 border-b border-gray-200/60 bg-white/50 backdrop-blur-md">
        <div className="flex-1 min-w-0 pr-4">
          <h1 className="text-xl sm:text-2xl font-black text-gray-900 tracking-tight uppercase truncate">
            {assignmentTitle || 'Assignment Generation'}
          </h1>
          <div className="flex items-center gap-3 mt-1.5 text-xs sm:text-sm font-semibold text-gray-500 uppercase tracking-widest overflow-hidden">
            <span className="truncate">{resolvedSubjectName}</span>
            <span className="w-1.5 h-1.5 flex-shrink-0 rounded-full bg-gray-300" />
            <span className="flex-shrink-0">{resolvedClassName}</span>
            <span className="w-1.5 h-1.5 flex-shrink-0 rounded-full bg-gray-300" />
            <span className="truncate">{cleanedSchoolName}</span>
          </div>
        </div>
      </div>
      {showProgress && (
        <div className="absolute top-5 right-5 z-50 flex items-center gap-3 bg-white px-4 sm:px-5 py-2.5 rounded-full shadow-xl border border-gray-200/90">
          <span className="text-xs sm:text-sm font-bold text-gray-700 tracking-wide uppercase">Generating</span>
          <span className="h-3 w-3 rounded-full bg-orange-500 animate-pulse" />
        </div>
      )}

      <div className="flex-1 flex flex-col items-center justify-center relative px-6 py-12 w-full min-h-[500px]">
        <div>
          {showSuccess ? (
            <div className="w-full flex-1 flex flex-col items-center justify-center py-6">
              <SuccessView
                assignmentId={assignmentId}
                isPartial={isPartial}
                generatedCount={generatedQuestionCount}
                requestedCount={requestedQuestionCount}
                generatedMarks={generatedMarks}
                requestedMarks={requestedMarks}
                duration={duration}
                subject={resolvedSubjectName}
                schoolName={cleanedSchoolName}
                className={resolvedClassName}
                onRegenerate={onRetry}
                isRetrying={isRetrying}
              />
            </div>
          ) : showError ? (
            <div className="w-full h-full flex flex-col items-center justify-center">
              <ErrorView error={error} onRetry={onRetry} isRetrying={isRetrying} />
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center text-center max-w-4xl w-full">
              
              <div className="relative flex items-center justify-center mb-16">
                <svg className="w-52 h-52 sm:w-64 sm:h-64 transform -rotate-90" viewBox="0 0 100 100">
                  <circle
                    className="text-gray-200 stroke-current"
                    strokeWidth="4"
                    cx="50" cy="50" r="46"
                    fill="transparent"
                  />
                  <circle
                    className="text-orange-500 stroke-current"
                    strokeWidth="4"
                    strokeLinecap="round"
                    cx="50" cy="50" r="46"
                    fill="transparent"
                    strokeDasharray="289 289"
                    strokeDashoffset={progressStrokeOffset}
                  />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                  <span className="text-5xl sm:text-6xl font-black text-gray-900 tracking-tighter tabular-nums">
                    {Math.round(showSuccess ? 100 : Math.min(99, progress))}<span className="text-3xl sm:text-4xl text-gray-400 font-bold ml-1">%</span>
                  </span>
                </div>
                
                <div className="absolute inset-0 rounded-full border-4 border-orange-500/20" />
              </div>

              <div className="flex flex-col items-center px-4">
                <h2 className="text-5xl sm:text-6xl font-extrabold text-gray-900 tracking-tight text-center">
                  {currentStageInfo.label}
                </h2>
                <div className="mt-6 max-w-xl">
                  <p className="text-lg sm:text-xl text-gray-500 font-medium tracking-wide text-center">
                    {progressText}
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';
import { motion } from 'framer-motion';
import Link from 'next/link';
import { RefreshCw, Zap, CheckCircle2, FileText, Clock, Trophy } from 'lucide-react';

interface SuccessViewProps {
  assignmentId: string;
  isPartial: boolean;
  generatedCount: number | null | undefined;
  requestedCount: number | null | undefined;
  generatedMarks: number | null | undefined;
  requestedMarks: number | null | undefined;
  duration: number;
  subject?: string;
  schoolName?: string;
  className?: string;
  onRegenerate: () => void;
  isRetrying: boolean;
}

export function SuccessView({
  assignmentId, isPartial, generatedCount, requestedCount,
  generatedMarks, requestedMarks, duration, subject, schoolName, className,
  onRegenerate, isRetrying,
}: SuccessViewProps) {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.6, ease: 'easeOut' }}
      className="flex flex-col items-center justify-center w-full max-w-7xl mx-auto px-4 py-4 sm:py-6 gap-6 sm:gap-8 md:gap-10"
    >
      <div className="absolute top-0 left-0 w-full h-[50vh] bg-gradient-to-b from-emerald-50/80 to-transparent -z-10 pointer-events-none" />

      {/* Hero Section */}
      <motion.div 
        initial={{ scale: 0.95, opacity: 0, y: 20 }}
        animate={{ scale: 1, opacity: 1, y: 0 }}
        transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1], delay: 0.1 }}
        className="text-center flex flex-col items-center max-w-3xl flex-shrink-0"
      >
        <div className="relative flex items-center justify-center mb-3 mt-2">
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ type: "spring", stiffness: 200, damping: 20, delay: 0.2 }}
            className="w-16 h-16 sm:w-20 sm:h-20 bg-emerald-100 rounded-full flex items-center justify-center shadow-[0_0_30px_rgba(16,185,129,0.15)] relative z-10"
          >
            <CheckCircle2 className="w-8 h-8 sm:w-10 sm:h-10 text-emerald-600" strokeWidth={2.5} />
          </motion.div>
          <motion.div 
            animate={{ scale: [1, 1.2, 1], opacity: [0.2, 0, 0.2] }}
            transition={{ duration: 2.5, repeat: Infinity, ease: 'easeInOut' }}
            className="absolute inset-0 bg-emerald-400 rounded-full blur-lg z-0"
          />
        </div>

        <h1 className="text-3xl sm:text-4xl font-black text-gray-900 tracking-tight leading-[1.15] mb-2">
          {isPartial ? 'Partially Generated' : 'Assignment Ready'}
        </h1>
        
        <p className="text-sm sm:text-base text-gray-500 font-medium max-w-2xl leading-relaxed">
          {isPartial
            ? `We successfully generated ${generatedCount ?? 'some'} out of ${requestedCount ?? '?'} questions. You can view the partial results or regenerate.`
            : 'The AI has finished crafting your assignment. It is perfectly structured and ready for review.'}
        </p>
      </motion.div>

      {/* Stats Section */}
      <motion.div 
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, ease: 'easeOut', delay: 0.3 }}
        className="grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-8 w-full max-w-4xl px-6 flex-shrink-0"
      >
        {[
          { label: 'Questions', value: generatedCount !== null && generatedCount !== undefined ? `${generatedCount}/${requestedCount}` : (requestedCount ?? '-'), icon: FileText, color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'Total Marks', value: generatedMarks !== null && generatedMarks !== undefined ? `${generatedMarks}/${requestedMarks}` : (requestedMarks ?? '-'), icon: Trophy, color: 'text-amber-600', bg: 'bg-amber-50' },
          { label: 'Duration', value: `${duration} min`, icon: Clock, color: 'text-purple-600', bg: 'bg-purple-50' },
        ].map((stat, idx) => (
          <motion.div 
            key={stat.label}
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.4, delay: 0.4 + idx * 0.1 }}
            className="flex flex-col items-center justify-center relative p-1 flex-shrink-0"
          >
            <div className="flex items-center gap-2 mb-2">
              <div className={`p-2 rounded-lg ${stat.bg} ${stat.color}`}>
                <stat.icon className="w-5 h-5" />
              </div>
              <span className="text-xs sm:text-sm font-bold text-gray-500 uppercase tracking-widest">{stat.label}</span>
            </div>
            <div>
              <span className="text-4xl sm:text-5xl font-extrabold text-gray-900 tracking-tight">{String(stat.value)}</span>
            </div>
          </motion.div>
        ))}
      </motion.div>

      {/* Actions */}
      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4, delay: 0.6 }}
        className="flex flex-col sm:flex-row items-center justify-center gap-3 sm:gap-4 w-full max-w-xl flex-shrink-0"
      >
        <Link
          href={`/assignments/${assignmentId}/paper`}
          className="flex-1 flex items-center justify-center gap-2.5 w-full bg-gray-900 text-white rounded-full px-6 py-3.5 sm:py-4 text-base sm:text-lg font-bold shadow-lg shadow-gray-900/10 hover:bg-gray-800 hover:scale-[1.02] transition-all duration-300 min-h-[48px] sm:min-h-[54px]"
        >
          <Zap className="w-4 h-4 sm:w-5 sm:h-5" />
          {isPartial ? 'View Partial Paper' : 'View Assignment'}
        </Link>
        <button
          onClick={onRegenerate}
          disabled={isRetrying}
          className="flex-1 flex items-center justify-center gap-2.5 w-full bg-white text-gray-800 border border-gray-200 rounded-full px-6 py-3.5 sm:py-4 text-base sm:text-lg font-bold shadow-sm hover:bg-gray-50 hover:border-gray-300 hover:scale-[1.02] transition-all duration-300 disabled:opacity-50 disabled:hover:scale-100 min-h-[48px] sm:min-h-[54px]"
        >
          <RefreshCw className={`w-4 h-4 sm:w-5 sm:h-5 ${isRetrying ? 'animate-spin' : ''}`} />
          {isRetrying ? 'Regenerating...' : 'Regenerate'}
        </button>
      </motion.div>
    </motion.div>
  );
}

