'use client';

import React, { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import toast from 'react-hot-toast';
import { AlertCircle, CheckCircle2, Clock } from 'lucide-react';

interface UsageStats {
  userId: string;
  type: 'quiz' | 'paper' | 'assignment';
  limit: number;
  used: number;
  remaining: number;
  resetAt: string;
}

interface Props {
  type: 'quiz' | 'paper' | 'assignment';
  showFullStatus?: boolean;
}

export function DailyLimitIndicator({ type, showFullStatus = false }: Props) {
  const [stats, setStats] = useState<UsageStats | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchStats = async () => {
    try {
      const response = await api.get('/usage/daily-stats');
      if (response.data?.success) {
        const typeStats = response.data.data.find((s: UsageStats) => s.type === type);
        setStats(typeStats || null);
      }
    } catch (error) {
      console.error('Failed to fetch usage stats', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStats();
    // Refresh every minute
    const interval = setInterval(fetchStats, 60000);
    return () => clearInterval(interval);
  }, []);

  if (loading || !stats) {
    return null;
  }

  const percentage = (stats.used / stats.limit) * 100;
  const isWarning = stats.remaining <= 1;
  const isExceeded = stats.remaining <= 0;

  const typeLabels = {
    quiz: 'Mock Quizzes',
    paper: 'Question Papers',
    assignment: 'Assignments',
  };

  const resetDate = new Date(stats.resetAt);
  const resetTime = resetDate.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

  return (
    <div className="flex items-center gap-3 px-4 py-2 bg-blue-50 border border-blue-200 rounded-lg">
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 mb-1">
          <span className="text-sm font-medium text-gray-700">
            {typeLabels[type]}
          </span>
          {isExceeded && <AlertCircle size={16} className="text-red-500" />}
          {isWarning && !isExceeded && <AlertCircle size={16} className="text-amber-500" />}
          {!isWarning && !isExceeded && <CheckCircle2 size={16} className="text-green-500" />}
        </div>

        <div className="w-full bg-gray-200 rounded-full h-2">
          <div
            className={`h-2 rounded-full transition-all ${
              isExceeded ? 'bg-red-500' : isWarning ? 'bg-amber-500' : 'bg-green-500'
            }`}
            style={{ width: `${Math.min(percentage, 100)}%` }}
          />
        </div>

        {showFullStatus && (
          <div className="mt-2 flex items-center gap-2 text-xs text-gray-600">
            <span>
              {stats.used} of {stats.limit} used
            </span>
            <span className="text-gray-400">•</span>
            <Clock size={12} />
            <span>Resets at {resetTime}</span>
          </div>
        )}
      </div>

      <div className="flex-shrink-0 text-right">
        <div className={`text-sm font-bold ${
          isExceeded ? 'text-red-600' : isWarning ? 'text-amber-600' : 'text-green-600'
        }`}>
          {stats.remaining} left
        </div>
      </div>
    </div>
  );
}

interface FullStatusProps {
  showDialog?: boolean;
}

export function DailyLimitStatus({ showDialog = false }: FullStatusProps) {
  const [stats, setStats] = useState<UsageStats[]>([]);
  const [loading, setLoading] = useState(true);
  const [isOpen, setIsOpen] = useState(showDialog);

  const fetchStats = async () => {
    try {
      const response = await api.get('/usage/daily-stats');
      if (response.data?.success) {
        setStats(response.data.data);
      }
    } catch (error) {
      console.error('Failed to fetch usage stats', error);
      toast.error('Failed to load usage statistics');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStats();
  }, []);

  const typeLabels = {
    quiz: 'Mock Quizzes',
    paper: 'Question Papers',
    assignment: 'Assignments',
  };

  return (
    <div className="space-y-4">
      {loading ? (
        <div className="flex items-center justify-center py-8">
          <div className="text-gray-500">Loading usage statistics...</div>
        </div>
      ) : stats.length === 0 ? (
        <div className="text-center py-8 text-gray-500">
          No daily limits configured for your role
        </div>
      ) : (
        stats.map((stat) => (
          <div key={`${stat.userId}-${stat.type}`} className="p-4 border rounded-lg">
            <div className="flex items-center justify-between mb-3">
              <div>
                <h4 className="font-semibold text-gray-900">
                  {typeLabels[stat.type as keyof typeof typeLabels]}
                </h4>
                <p className="text-sm text-gray-600">
                  {stat.used} of {stat.limit} used today
                </p>
              </div>
              <div className={`text-lg font-bold ${
                stat.remaining <= 0 ? 'text-red-600' : 
                stat.remaining <= 1 ? 'text-amber-600' : 
                'text-green-600'
              }`}>
                {stat.remaining} remaining
              </div>
            </div>

            <div className="w-full bg-gray-200 rounded-full h-2.5">
              <div
                className={`h-2.5 rounded-full transition-all ${
                  stat.remaining <= 0 ? 'bg-red-500' :
                  stat.remaining <= 1 ? 'bg-amber-500' :
                  'bg-green-500'
                }`}
                style={{ width: `${Math.min((stat.used / stat.limit) * 100, 100)}%` }}
              />
            </div>

            <div className="mt-2 text-xs text-gray-500">
              Resets on {new Date(stat.resetAt).toLocaleDateString()} at {new Date(stat.resetAt).toLocaleTimeString()}
            </div>
          </div>
        ))
      )}
    </div>
  );
}

'use client';

import React from 'react';

type AvatarSize = 'sm' | 'md' | 'lg';

interface AvatarProps {
  name: string;
  imageUrl?: string;
  size?: AvatarSize;
}

const sizeMap: Record<AvatarSize, { width: number; height: number; fontSize: number }> = {
  sm: { width: 28, height: 28, fontSize: 11 },
  md: { width: 36, height: 36, fontSize: 13 },
  lg: { width: 48, height: 48, fontSize: 16 },
};

function getInitials(name: string): string {
  return name
    .split(' ')
    .map((n) => n.charAt(0).toUpperCase())
    .slice(0, 2)
    .join('');
}

export function Avatar({ name, imageUrl, size = 'md' }: AvatarProps) {
  const dims = sizeMap[size];
  return (
    <div
      style={{
        width: dims.width,
        height: dims.height,
        borderRadius: '50%',
        background: imageUrl ? 'transparent' : 'linear-gradient(135deg, #E8531D, #F97316)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        flexShrink: 0,
        overflow: 'hidden',
      }}
    >
      {imageUrl ? (
        <img src={imageUrl} alt={name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
      ) : (
        <span style={{ fontSize: dims.fontSize, fontWeight: 700, color: 'white', lineHeight: 1 }}>
          {getInitials(name)}
        </span>
      )}
    </div>
  );
}

'use client';

import React from 'react';
import { EmptyState } from './EmptyState';
import { LoadingState } from './LoadingState';

interface Column {
  key: string;
  header: string;
  render?: (value: any, row: any) => React.ReactNode;
  width?: string;
  align?: 'left' | 'center' | 'right';
}

interface DataTableProps {
  columns: Column[];
  data: any[];
  loading?: boolean;
  emptyMessage?: string;
  emptyIcon?: React.ReactNode;
  onRowClick?: (row: any) => void;
  className?: string;
}

export function DataTable({ columns, data, loading, emptyMessage = 'No data found', emptyIcon, onRowClick, className }: DataTableProps) {
  if (loading) {
    return <LoadingState lines={5} />;
  }

  if (!data || data.length === 0) {
    return (
      <EmptyState
        icon={emptyIcon}
        title={emptyMessage}
        description="There's nothing here yet. Data will appear once available."
      />
    );
  }

  return (
    <div className={className} style={{ overflowX: 'auto', width: '100%' }}>
      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 'var(--text-sm)' }}>
        <thead>
          <tr style={{ borderBottom: '1px solid var(--border)' }}>
            {columns.map((col) => (
              <th
                key={col.key}
                style={{
                  textAlign: col.align || 'left',
                  padding: '10px 14px',
                  fontWeight: 600,
                  color: 'var(--text-muted)',
                  fontSize: 'var(--text-xs)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.05em',
                  whiteSpace: 'nowrap',
                  width: col.width,
                }}
              >
                {col.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map((row, idx) => (
            <tr
              key={row.id || idx}
              onClick={() => onRowClick?.(row)}
              style={{
                borderBottom: '1px solid var(--border)',
                cursor: onRowClick ? 'pointer' : undefined,
                transition: 'background 0.1s',
              }}
              onMouseEnter={(e) => { e.currentTarget.style.background = 'var(--bg-hover)'; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; }}
            >
              {columns.map((col) => (
                <td
                  key={col.key}
                  style={{
                    textAlign: col.align || 'left',
                    padding: '12px 14px',
                    color: 'var(--text-primary)',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                  }}
                >
                  {col.render ? col.render(row[col.key], row) : row[col.key]}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

