  width?: string;
}

interface TableProps {
  columns: Column[];
  data: any[];
  loading?: boolean;
  emptyMessage?: string;
  onRowClick?: (row: any) => void;
}

export function Table({ columns, data, loading, emptyMessage = 'No data found', onRowClick }: TableProps) {
  if (loading) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, padding: 16 }}>
        {Array.from({ length: 5 }).map((_, i) => (
          <div
            key={i}
            style={{
              height: 40,
              background: 'linear-gradient(90deg, #F3F4F6 25%, #E5E7EB 50%, #F3F4F6 75%)',
              backgroundSize: '200% 100%',
              animation: 'skeleton-shimmer 1.5s infinite',
              borderRadius: 8,
            }}
          />
        ))}
      </div>
    );
  }

  if (!data || data.length === 0) {
    return (
      <div
        style={{
          textAlign: 'center',
          padding: '48px 24px',
          color: 'var(--text-muted)',
          fontSize: 'var(--text-sm)',
        }}
      >
        {emptyMessage}
      </div>
    );
  }

  return (
    <div style={{ overflowX: 'auto', width: '100%' }}>
      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 'var(--text-sm)' }}>
        <thead>
          <tr style={{ borderBottom: '1px solid var(--border)' }}>
            {columns.map((col) => (
              <th
                key={col.key}
                style={{
                  textAlign: 'left',
                  padding: '12px 16px',
                  fontWeight: 600,
                  color: 'var(--text-muted)',
                  fontSize: 'var(--text-xs)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.05em',
                  whiteSpace: 'nowrap',
                  width: col.width,
                }}
              >
                {col.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map((row, idx) => (
            <tr
              key={row.id || idx}
              onClick={() => onRowClick?.(row)}
              style={{
                borderBottom: '1px solid var(--border)',
                cursor: onRowClick ? 'pointer' : undefined,
                transition: 'background 0.1s',
              }}
              onMouseEnter={(e) => { e.currentTarget.style.background = 'var(--bg-hover)'; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; }}
            >
              {columns.map((col) => (
                <td
                  key={col.key}
                  style={{
                    padding: '12px 16px',
                    color: 'var(--text-primary)',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                  }}
                >
                  {col.render ? col.render(row[col.key], row) : row[col.key]}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

'use client';

import axios from 'axios';
import { joinUrl, resolveApiOrigin } from '@/utils/url';

const isApiDebugEnabled =
  process.env.NODE_ENV !== 'production' || process.env.NEXT_PUBLIC_API_DEBUG === 'true';

function getBaseURL(): string {
  const origin = resolveApiOrigin();
  return origin.endsWith('/api/v1') ? origin : `${origin}/api/v1`;
}

export const api = axios.create({
  withCredentials: true,
  timeout: 60000,
  headers: {
    'Content-Type': 'application/json',
  },
});

api.interceptors.request.use(async (config) => {
  config.baseURL = getBaseURL();

  // Dynamic import to break dependency cycle
  try {
    const { useAuthStore } = await import('@/store/auth.store');
    const token = useAuthStore.getState().accessToken;
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
  } catch (err) {
    // Ignore errors during boot
  }

  // Attach organization context header from admin-auth store
  try {
    const { useAdminAuthStore } = await import('@/store/admin-auth.store');
    const orgId = useAdminAuthStore.getState().activeOrganizationId;
    if (orgId) {
      config.headers['X-Organization-Id'] = orgId;
    }
  } catch (err) {
    // Ignore errors during boot
  }

  if (typeof FormData !== 'undefined' && config.data instanceof FormData) {
    if (config.headers) {
      delete config.headers['Content-Type'];
    }
  }

  const endpoint = config.url ?? '';
  const finalURL = config.baseURL ? joinUrl(config.baseURL, endpoint) : endpoint;
  (config as typeof config & { metadata?: { startedAt: number } }).metadata = {
    startedAt: Date.now(),
  };

  if (isApiDebugEnabled) {
    console.log('[API REQUEST]', {
      method: config.method?.toUpperCase() ?? 'GET',
      baseURL: config.baseURL,
      endpoint,
      finalURL,
    });
  }

  return config;
});

let isRefreshing = false;
let failedQueue: Array<{ resolve: (value?: unknown) => void; reject: (reason?: any) => void }> = [];

const processQueue = (error: any, token: string | null = null) => {
  failedQueue.forEach(prom => {
    if (error) {
      prom.reject(error);
    } else {
      prom.resolve(token);
    }
  });
  failedQueue = [];
};

api.interceptors.response.use(
  (response) => {
    if (isApiDebugEnabled) {
      const startedAt = (
        response.config as typeof response.config & { metadata?: { startedAt?: number } }
      ).metadata?.startedAt;
      const durationMs = typeof startedAt === 'number' ? Date.now() - startedAt : undefined;
      console.log('[API RESPONSE]', {
        method: response.config.method?.toUpperCase() ?? 'GET',
        status: response.status,
        url: response.config.url,
        durationMs,
      });
    }
    return response;
  },
  async (error) => {
    if (axios.isAxiosError(error)) {
      const status = error.response?.status;
      const backendMessage =
        (error.response?.data as { error?: string; message?: string } | undefined)?.error ??
        (error.response?.data as { error?: string; message?: string } | undefined)?.message;
      const message = backendMessage ?? error.message ?? 'An unexpected error occurred';

      if (isApiDebugEnabled) {
        console.warn('[API ERROR]', {
          status,
          method: error.config?.method?.toUpperCase(),
          baseURL: error.config?.baseURL,
          endpoint: error.config?.url,
          finalURL:
            error.config?.baseURL && error.config?.url
              ? joinUrl(error.config.baseURL, error.config.url)
              : error.config?.url,
          code: error.code,
          message: error.message,
          response: error.response?.data,
        });
      }

      const originalRequest = error.config;

      // Handle unauthorized errors automatically with token refresh
      if (status === 401 && originalRequest && !originalRequest.url?.includes('/auth/refresh') && !originalRequest.url?.includes('/auth/login')) {
        if (!isRefreshing) {
          isRefreshing = true;
          try {
            // Attempt to refresh the token using a clean axios instance to avoid interceptor loops
            const refreshUrl = originalRequest.baseURL ? joinUrl(originalRequest.baseURL, '/auth/refresh') : '/auth/refresh';
            const res = await axios.post(refreshUrl, {}, { withCredentials: true });
            const token = res.data?.data?.accessToken;
            
            if (token) {
              const { useAuthStore } = await import('@/store/auth.store');
              const user = useAuthStore.getState().user;
              if (user) {
                useAuthStore.getState().setAuth(user, token);
              }
              
              processQueue(null, token);
              originalRequest.headers.Authorization = `Bearer ${token}`;
              return api(originalRequest);
            } else {
              throw new Error('No access token returned from refresh');
            }
          } catch (refreshError) {
            processQueue(refreshError, null);
            try {
              const { useAuthStore } = await import('@/store/auth.store');
              useAuthStore.getState().clearAuth();
            } catch {
              // ignore
            }
            return Promise.reject(new Error('Session expired. Please log in again.'));
          } finally {
            isRefreshing = false;
          }
        } else {
          return new Promise((resolve, reject) => {
            failedQueue.push({ resolve, reject });
          }).then(token => {
            if (originalRequest.headers) {
              originalRequest.headers.Authorization = `Bearer ${token}`;
            }
            return api(originalRequest);
          }).catch(err => {
            return Promise.reject(err);
          });
        }
      } else if (status === 401) {
        // If the refresh token itself expired or failed, clear auth
        try {
          const { useAuthStore } = await import('@/store/auth.store');
          useAuthStore.getState().clearAuth();
        } catch {
          // ignore
        }
      }

      return Promise.reject(new Error(message));
    }

    if (isApiDebugEnabled) {
      console.warn('[API ERROR]', {
        message: error instanceof Error ? error.message : String(error),
      });
    }
    return Promise.reject(error);
  }
);

export function getApiOrigin(): string {
  return resolveApiOrigin();
}

export function getApiBaseUrl(): string {
  return getBaseURL();
}

import { create } from 'zustand';
import { api } from '@/lib/api';

export interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  role: string;
  organizationId: string | null;
  organizationName: string | null;
  departmentName: string | null;
  departmentId: string | null;
  forcePasswordReset?: boolean;
  preferences: {
    emailNotifications?: boolean;
    inAppAlerts?: boolean;
    autoSave?: boolean;
    weeklyDigest?: boolean;
    [key: string]: any;
  };
  hasCompletedOnboarding?: boolean;
}

interface AuthStore {
  user: User | null;
  accessToken: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  setAuth: (user: User, token: string) => void;
  clearAuth: () => void;
  initialize: () => Promise<boolean>;
  login: (email: string, password: string) => Promise<{ success: boolean; error?: string }>;
  ssoLogin: (data: {
    email: string;
    firstName?: string;
    lastName?: string;
    provider: string;
    token?: string;
  }) => Promise<{ success: boolean; error?: string }>;
  signup: (data: {
    email: string;
    password?: string;
    firstName: string;
    lastName: string;
    role: 'STUDENT' | 'TEACHER';
    organizationId: string;
  }) => Promise<{ success: boolean; error?: string }>;
  logout: () => Promise<void>;
  updateProfile: (data: { firstName?: string; lastName?: string; email?: string }) => Promise<{ success: boolean; error?: string }>;
  updateOrganization: (data: { organizationName: string; department: string; academicYear?: string }) => Promise<{ success: boolean; error?: string }>;
  completeOnboarding: (data: {
    firstName: string;
    lastName: string;
    organizationName: string;
    department: string;
    className: string;
    subject: string;
    students: Array<{ name: string; rollNo: string; email: string }>;
  }) => Promise<{ success: boolean; error?: string }>;
}

export const useAuthStore = create<AuthStore>((set, get) => ({
  user: null,
  accessToken: null,
  isAuthenticated: false,
  isLoading: true,

  setAuth: (user, token) => {
    set({ user, accessToken: token, isAuthenticated: true, isLoading: false });
  },

  clearAuth: () => {
    set({ user: null, accessToken: null, isAuthenticated: false, isLoading: false });
  },

  initialize: async () => {
    try {
      if (!get().isAuthenticated) {
        set({ isLoading: true });
      }
      const refreshRes = await api.post('/auth/refresh');
      const token = refreshRes.data?.data?.accessToken;

      if (token) {
        set({ accessToken: token });
        const meRes = await api.get('/auth/me');
        const user = meRes.data?.data;

        if (user) {
          set({
            user,
            accessToken: token,
            isAuthenticated: true,
            isLoading: false,
          });
          return true;
        }
      }
      if (!get().isAuthenticated) get().clearAuth();
      else set({ isLoading: false });
      return false;
    } catch (err) {
      if (!get().isAuthenticated) get().clearAuth();
      else set({ isLoading: false });
      return false;
    }
  },

  login: async (email, password) => {
    try {
      set({ isLoading: true });
      const res = await api.post('/auth/login', { email, password });
      const { accessToken, user } = res.data?.data || {};
      if (accessToken && user) {
        set({
          user,
          accessToken,
          isAuthenticated: true,
          isLoading: false,
        });
        return { success: true };
      }
      set({ isLoading: false });
      return { success: false, error: 'Invalid response from auth server.' };
    } catch (err: any) {
      set({ isLoading: false });
      return { success: false, error: err.message || 'Login failed.' };
    }
  },

  ssoLogin: async (data) => {
    try {
      set({ isLoading: true });
      const res = await api.post('/auth/sso', data);
      const { accessToken, user } = res.data?.data || {};
      if (accessToken && user) {
        set({
          user,
          accessToken,
          isAuthenticated: true,
          isLoading: false,
        });
        return { success: true };
      }
      set({ isLoading: false });
      return { success: false, error: 'Invalid response from auth server.' };
    } catch (err: any) {
      set({ isLoading: false });
      return { success: false, error: err.message || 'SSO Login failed.' };
    }
  },

  signup: async (data) => {
    try {
      set({ isLoading: true });
      const res = await api.post('/auth/signup', data);
      const { accessToken, user } = res.data?.data || {};
      if (accessToken && user) {
        set({
          user,
          accessToken,
          isAuthenticated: true,
          isLoading: false,
        });
        return { success: true };
      }
      set({ isLoading: false });
      return { success: false, error: 'Invalid response from auth server.' };
    } catch (err: any) {
      set({ isLoading: false });
      return { success: false, error: err.message || 'Signup failed.' };
    }
  },

  logout: async () => {
    try {
      await api.post('/auth/logout');
    } catch (err) {
      // Ignore failures on logout endpoint and proceed to clear client auth
    } finally {
      get().clearAuth();
    }
  },

  updateProfile: async (data) => {
    try {
      const res = await api.put('/auth/me/profile', data);
      const updatedUser = res.data?.data;
      if (updatedUser) {
        set((state) => ({
          user: state.user ? { ...state.user, ...updatedUser } : null,
        }));
        return { success: true };
      }
      return { success: false, error: 'Failed to update profile.' };
    } catch (err: any) {
      return { success: false, error: err.message || 'Profile update failed.' };
    }
  },

  updateOrganization: async (data) => {
    try {
      const res = await api.put('/auth/me/organization', data);
      if (res.data?.success) {
        // Refresh profile details to get accurate names
        const meRes = await api.get('/auth/me');
        const user = meRes.data?.data;
        if (user) {
          set({ user });
        }
        return { success: true };
      }
      return { success: false, error: 'Failed to update organization settings.' };
    } catch (err: any) {
      return { success: false, error: err.message || 'Organization update failed.' };
    }
  },

  completeOnboarding: async (data) => {
    try {
      // 1. Update personal profile name if changed
      await api.put('/auth/me/profile', {
        firstName: data.firstName,
        lastName: data.lastName,
      });

      // 2. Setup organization & department
      await api.put('/auth/me/organization', {
        organizationName: data.organizationName,
        department: data.department,
        academicYear: '2026-2027',
      });

      // 3. Create class group
      const groupRes = await api.post('/groups', {
        name: data.className,
        subject: data.subject,
      });
      const group = groupRes.data?.data;

      // 4. Bulk add students if any were configured
      if (group?.id && data.students.length > 0) {
        await api.post(`/groups/${group.id}/students/bulk`, {
          students: data.students,
        });
      }

      // 5. Update user onboarding status
      await api.post('/auth/onboarding/complete');

      // 6. Refresh user profile
      const meRes = await api.get('/auth/me');
      const user = meRes.data?.data;
      if (user) {
        set({ user });
      }

      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message || 'Onboarding failed.' };
    }
  },
}));
